INSERT INTO quiz_questions (id, topic_id, level_number, statement, answer, hint, explanation, fun_fact, source, status, active, updated_at) VALUES
  ('my-cycle-1-09', 'my-cycle', 1, 'Period blood should always be bright red.', 'myth', 'Think about what happens to blood that’s been around a little while.', 'Nope! Bright red, dark red, pink or brown are all normal. Brown is just older blood that took its time leaving.', 'Brown blood is common at the very start or end of a period.', 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-1-10', 'my-cycle', 1, 'It’s normal for your period to turn up a few days earlier or later than you expected.', 'fact', 'Are bodies clockwork?', 'Yep! Cycles can shift by a few days from month to month, especially in your first few years.', 'Logging a few cycles helps Spot it learn your own rhythm.', 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-2-09', 'my-cycle', 2, 'Ovulation can happen from either ovary, and they don’t strictly take turns.', 'fact', 'Is there a rota?', 'True! Each cycle one ovary usually releases an egg, but it isn’t a neat left-right-left pattern.', 'Some people notice their mid-cycle twinge switches sides, but not always.', 'ACOG: Your menstrual cycle', 'draft', true, now()),
  ('my-cycle-2-10', 'my-cycle', 2, 'Everyone can feel the exact moment their egg is released.', 'myth', 'How many people do you know who mention it?', 'Nope! Most people feel nothing. Some get a one-sided twinge called mittelschmerz, which is German for ‘middle pain’.', 'Mittelschmerz can last from a few minutes to a day or two.', 'NHS: Ovulation pain', 'draft', true, now()),
  ('my-cycle-3-09', 'my-cycle', 3, 'The part of your cycle after ovulation is called the luteal phase.', 'fact', 'It’s named after something yellow.', 'Yep! It’s named after the corpus luteum, the ‘yellow body’ left behind in the ovary after an egg is released.', '‘Luteum’ is Latin for yellow.', 'ACOG: Your menstrual cycle', 'draft', true, now()),
  ('my-cycle-3-10', 'my-cycle', 3, 'Your womb lining stays the same thickness all month.', 'myth', 'What does your period actually shed?', 'Nope! The lining builds up after your period, gets thicker after ovulation, then sheds if there’s no pregnancy.', 'The lining can grow several times thicker in a single cycle.', 'NHS: Periods', 'draft', true, now()),
  ('period-myths-1-09', 'period-myths', 1, 'Everyone can tell when you’re on your period.', 'myth', 'Can you tell when your friends are?', 'Nope! Unless you tell them, people really can’t tell. Period products are made to be invisible.', 'Plenty of athletes compete on their period and nobody knows.', 'NHS: Periods', 'draft', true, now()),
  ('period-myths-1-10', 'period-myths', 1, 'Period blood attracts sharks, so you can’t swim in the sea.', 'myth', 'Ask the people who study shark bites.', 'Myth! Shark researchers have found no evidence that people on their period are at higher risk. Sea swims are fine.', 'Water pressure means very little period blood leaves your body while you swim anyway.', 'Florida Museum: International Shark Attack File', 'draft', true, now()),
  ('period-myths-2-09', 'period-myths', 2, 'Period pain can spread to your lower back and thighs.', 'fact', 'Is it always just your tummy?', 'Yep! Cramps often spread to your back and the tops of your legs. A heat pad on your back can help too.', 'Some people get a dull ache before their period even starts.', 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-10', 'period-myths', 2, 'Painkillers work best if you wait until cramps are at their worst.', 'myth', 'Is it easier to stop a fire early or late?', 'Nope! Anti-inflammatory painkillers like ibuprofen tend to work better when taken as soon as the pain starts. Always check the label first.', 'They work by calming down the chemicals that cause cramps.', 'ACOG: Dysmenorrhea', 'draft', true, now()),
  ('period-myths-3-09', 'period-myths', 3, 'You have to throw away a menstrual cup after every period.', 'myth', 'Think ‘reusable’.', 'Nope! With proper cleaning, a menstrual cup can last for years.', 'One cup can replace thousands of pads or tampons over its life.', 'NHS: Periods', 'draft', true, now()),
  ('period-myths-3-10', 'period-myths', 3, 'Flushing pads or tampons down the toilet can block pipes.', 'fact', 'Where does it all end up?', 'True! Pads and tampons don’t break down in water. Wrap them up and pop them in the bin.', 'Blocked sewers are often full of things that should have gone in the bin.', 'Water UK: Bin it, don’t block it', 'draft', true, now()),
  ('body-changes-1-09', 'body-changes', 1, 'Feeling more self-conscious about your body during puberty is really common.', 'fact', 'Are you the only one?', 'Yep! Your body is changing fast, so it makes sense to notice it more. Everyone around you is going through it too.', 'Talking to a trusted adult or friend can make it feel lighter.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-10', 'body-changes', 1, 'Girls and boys start puberty at exactly the same age.', 'myth', 'Look around your class.', 'Nope! Girls usually start puberty a year or two earlier than boys.', 'That’s why girls are often taller than boys for a while.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-09', 'body-changes', 2, 'Your hands and feet can grow before the rest of you during puberty.', 'fact', 'Ever needed new shoes before new trousers?', 'Yep! Hands and feet often grow first, so it’s normal to feel a bit out of proportion for a while.', 'Your arms and legs usually catch up next, then your body.', 'Nemours KidsHealth: Puberty', 'draft', true, now()),
  ('body-changes-2-10', 'body-changes', 2, 'Breasts stop growing the moment your first period arrives.', 'myth', 'Does everything change on one day?', 'Nope! Breasts usually keep developing for a few years after periods start.', 'Breast development often finishes in your late teens.', 'Nemours KidsHealth: Breasts and bras', 'draft', true, now()),
  ('body-changes-3-09', 'body-changes', 3, 'Dried discharge can leave a yellowish mark on your underwear, and that’s normal.', 'fact', 'What colour does clear liquid leave when it dries?', 'Yep! Healthy discharge is clear or white, but it can dry a little yellow on fabric.', 'Discharge naturally keeps your vagina clean and healthy.', 'NHS: Vaginal discharge', 'draft', true, now()),
  ('body-changes-3-10', 'body-changes', 3, 'Tight leggings and jeans always cause infections.', 'myth', 'Is it ‘always’ or ‘sometimes for some people’?', 'Not always! Tight clothes don’t cause infections on their own. If you get thrush a lot, loose cotton underwear can help.', 'Changing out of sweaty gym kit soon after exercise helps too.', 'NHS: Thrush', 'draft', true, now()),
  ('period-care-1-09', 'period-care', 1, 'Period pants can be worn on their own or as a back-up with a tampon or cup.', 'fact', 'Can they team up?', 'Yep! Use them alone on lighter days or as leak back-up on heavier ones.', 'Some period pants hold as much as a few tampons.', 'NHS: Periods', 'draft', true, now()),
  ('period-care-1-10', 'period-care', 1, 'Panty liners are made for heavy-flow days.', 'myth', 'Think about how thin they are.', 'Nope! Liners are very thin and are for discharge or the very lightest days. On heavier days you’ll need a pad, tampon, cup or period pants.', 'Liners are great for the last day of your period.', 'NHS: Periods', 'draft', true, now()),
  ('period-care-2-09', 'period-care', 2, 'Counting how many pads or tampons you use a day can help a doctor tell if your periods are heavy.', 'fact', 'What do doctors like to measure?', 'Yep! Jotting down how often you change helps a doctor understand your flow.', 'You can add notes like this in your Spot it log.', 'NHS: Heavy periods', 'draft', true, now()),
  ('period-care-2-10', 'period-care', 2, 'It’s fine to use a tampon to soak up discharge between periods.', 'myth', 'What are tampons designed for?', 'Nope! Tampons are for periods only. Using them when you’re not bleeding can dry you out and raise the small risk of toxic shock syndrome.', 'A liner is the better choice for discharge.', 'FDA: The facts on tampons', 'draft', true, now()),
  ('period-care-3-09', 'period-care', 3, 'A period that lasts more than 7 days is worth mentioning to a doctor.', 'fact', 'What’s the usual range?', 'Yep! Periods usually last 2 to 7 days. Longer ones can be checked to make sure everything is OK.', 'Long periods can be a reason for low iron.', 'NHS: Heavy periods', 'draft', true, now()),
  ('period-care-3-10', 'period-care', 3, 'Bleeding between periods every month is nothing to bother a doctor about.', 'myth', 'Is a regular surprise still a surprise?', 'Nope! Light spotting now and then can be normal, but regular bleeding between periods should be checked by a doctor.', 'Doctors hear about this a lot, so there’s no need to feel awkward.', 'NHS: Bleeding between periods', 'draft', true, now()),
  ('hormones-101-1-09', 'hormones-101', 1, 'The pituitary gland, about the size of a pea, sits just below your brain.', 'fact', 'Small but mighty.', 'Yep! This tiny gland sends hormones that tell your ovaries what to do each month.', 'It’s sometimes called the ‘master gland’.', 'NHS: Pituitary gland', 'draft', true, now()),
  ('hormones-101-1-10', 'hormones-101', 1, 'Only women make oestrogen.', 'myth', 'Do hormones belong to one sex?', 'Nope! Men make some oestrogen too. It helps keep their bones healthy.', 'Women make some testosterone too, so it works both ways.', 'Cleveland Clinic: Estrogen', 'draft', true, now()),
  ('hormones-101-2-09', 'hormones-101', 2, 'Follicle-stimulating hormone (FSH) helps eggs grow in the ovaries.', 'fact', 'The clue is in the name.', 'Yep! FSH from the pituitary wakes up follicles, the little sacs that each hold an egg.', 'Each follicle is like a tiny bubble around an egg.', 'Cleveland Clinic: Follicle-stimulating hormone', 'draft', true, now()),
  ('hormones-101-2-10', 'hormones-101', 2, 'The hormone that triggers ovulation is insulin.', 'myth', 'Two letters, made by the pituitary.', 'Nope! It’s LH (luteinising hormone). A sudden surge of LH tells the ovary to release an egg.', 'Ovulation tests look for this LH surge in your pee.', 'Cleveland Clinic: Luteinizing hormone', 'draft', true, now()),
  ('hormones-101-3-09', 'hormones-101', 3, 'Many people feel hungrier in the week or so before their period.', 'fact', 'Snack o’clock?', 'Yep! Appetite changes are a common PMS symptom, and hormones play a part.', 'Your body uses a little more energy after ovulation.', 'NHS: PMS', 'draft', true, now()),
  ('hormones-101-3-10', 'hormones-101', 3, 'Teen mood swings are caused only by hormones.', 'myth', 'What else is going on in a teen’s life?', 'Nope! Hormones play a part, but so do sleep, stress, school, friends and growing up. It’s a mix.', 'Sleep is one of the biggest mood boosters there is.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('skin-hormones-1-09', 'skin-hormones', 1, 'Hormones like testosterone can make the oil glands in your skin bigger and busier.', 'fact', 'Which hormones rise in puberty for everyone?', 'Yep! Androgens, including testosterone, boost oil production. More oil can mean more blocked pores.', 'Your face has more oil glands than almost anywhere else.', 'American Academy of Dermatology: Acne causes', 'draft', true, now()),
  ('skin-hormones-1-10', 'skin-hormones', 1, 'Spots are contagious.', 'myth', 'Can you catch them from a friend?', 'Nope! You can’t catch acne from someone else.', 'Acne is the most common skin condition in teens.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-2-09', 'skin-hormones', 2, 'Benzoyl peroxide, a common spot treatment, can bleach towels and pillowcases.', 'fact', 'Bleach-y name, bleach-y habits?', 'Yep! It can leave pale patches on fabric, so white towels and pillowcases are a smart idea.', 'It also works by killing the bacteria linked to spots.', 'American Academy of Dermatology: Benzoyl peroxide', 'draft', true, now()),
  ('skin-hormones-2-10', 'skin-hormones', 2, 'Oily skin doesn’t need moisturiser.', 'myth', 'Is oil the same as water?', 'Nope! Oily skin can still be dry or dehydrated, especially with spot treatments. A light, oil-free moisturiser helps.', 'Look for ‘non-comedogenic’ on the label.', 'American Academy of Dermatology: Oily skin', 'draft', true, now()),
  ('skin-hormones-3-09', 'skin-hormones', 3, 'Some contraceptive pills can help clear acne.', 'fact', 'Hormones in, oil out?', 'Yep! Certain combined pills can calm hormone-driven acne. A doctor can say if it’s a good fit for you.', 'It can take a few months to see the difference.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-3-10', 'skin-hormones', 3, 'You have to wait until acne is really bad before seeing a GP.', 'myth', 'Is there a minimum level of spots?', 'Nope! If spots bother you or treatments from the pharmacy aren’t working, you can see a GP at any time.', 'Treating acne early can help stop scars.', 'NHS: Acne', 'draft', true, now()),
  ('pcos-1-09', 'pcos', 1, 'In PCOS, the ‘cysts’ are actually small follicles that haven’t released an egg.', 'fact', 'Are they the scary kind?', 'Yep! They’re tiny fluid-filled sacs that each hold an egg that wasn’t released. They aren’t harmful.', 'The name PCOS is a bit misleading, and experts have talked about changing it.', 'NHS: PCOS', 'draft', true, now()),
  ('pcos-1-10', 'pcos', 1, 'You can only get PCOS after you’ve had children.', 'myth', 'When do the signs often show up?', 'Nope! Signs of PCOS often show up in the late teens or early twenties.', 'Many people find out when they try to work out why their periods are irregular.', 'NHS: PCOS', 'draft', true, now()),
  ('pcos-2-09', 'pcos', 2, 'PCOS can make it harder for your body to use insulin properly.', 'fact', 'Insulin is the hormone that handles sugar.', 'Yep! This is called insulin resistance, and it’s common in PCOS.', 'Insulin resistance can make the ovaries make more testosterone.', 'NHS: PCOS', 'draft', true, now()),
  ('pcos-2-10', 'pcos', 2, 'PCOS always causes weight gain.', 'myth', 'Is there an ‘always’ in PCOS?', 'Nope! Some people with PCOS gain weight more easily, but many don’t. PCOS looks different for everyone.', 'People of any size can have PCOS.', 'NHS: PCOS', 'draft', true, now()),
  ('pcos-3-09', 'pcos', 3, 'People with PCOS have a higher chance of getting type 2 diabetes later in life.', 'fact', 'Remember insulin?', 'Yep! Because of insulin resistance, the risk is higher. Healthy habits and regular check-ups help.', 'A simple blood test can check your blood sugar.', 'NHS: PCOS', 'draft', true, now()),
  ('pcos-3-10', 'pcos', 3, 'Laser hair removal makes PCOS worse.', 'myth', 'Does treating hair change your hormones?', 'Nope! Laser and other hair removal treatments don’t affect PCOS. They’re one way to manage extra hair.', 'Some medicines and creams can also slow hair growth.', 'NHS: PCOS', 'draft', true, now()),
  ('food-cycle-1-09', 'food-cycle', 1, 'Milk, yoghurt and fortified plant drinks help build strong bones.', 'fact', 'Which mineral do bones love?', 'Yep! They’re rich in calcium, and your teens are a key time for building bone.', 'Look for ‘fortified with calcium’ on plant drinks.', 'NHS: Calcium', 'draft', true, now()),
  ('food-cycle-1-10', 'food-cycle', 1, 'Drinking water on your period makes bloating worse.', 'myth', 'Does your body hold on to water when it’s short of it?', 'Nope! Staying hydrated can actually help ease bloating.', 'Water-rich foods like cucumber and watermelon count too.', 'Cleveland Clinic: Period bloating', 'draft', true, now()),
  ('food-cycle-2-09', 'food-cycle', 2, 'Beans, lentils and dark leafy greens all contain iron.', 'fact', 'Is iron only in meat?', 'Yep! Plant foods have iron too. Pair them with vitamin C to help your body absorb it.', 'A squeeze of lemon over greens is an easy iron hack.', 'NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-10', 'food-cycle', 2, 'Iron from spinach is absorbed just as easily as iron from meat.', 'myth', 'There are two types of iron.', 'Nope! Iron from plants (non-haem) is harder to absorb than iron from meat and fish (haem).', 'Popeye’s spinach fame came partly from an old maths mix-up about its iron.', 'NIH Office of Dietary Supplements: Iron', 'draft', true, now()),
  ('food-cycle-3-09', 'food-cycle', 3, 'Chamomile tea has been proven to cure period pain.', 'myth', 'Proven or soothing?', 'Not proven! A warm drink can feel comforting, but there isn’t strong evidence that it cures cramps.', 'Heat on your tummy has better evidence.', 'NHS: Period pain', 'draft', true, now()),
  ('food-cycle-3-10', 'food-cycle', 3, 'A very sugary snack can give a quick lift followed by a slump.', 'fact', 'What goes up...', 'Yep! Sugary foods can give a short burst of energy. Snacks with fibre or protein keep you going for longer.', 'Fruit with a handful of nuts is a steadier choice.', 'NHS: Eat well', 'draft', true, now()),
  ('mood-hormones-1-01', 'mood-hormones', 1, 'It’s normal for your mood to go up and down.', 'fact', 'Are you meant to feel the same every day?', 'Yep! Everyone has ups and downs. Moods shift with sleep, stress, hormones and what’s going on in your life.', 'Noticing your moods is the first step to looking after them.', 'NHS Every Mind Matters', 'draft', true, now()),
  ('mood-hormones-1-02', 'mood-hormones', 1, 'Feeling grumpy before your period means you’re just a moody person.', 'myth', 'Is it you or your cycle?', 'Nope! Irritability before a period is a really common PMS symptom. It says nothing about who you are.', 'Logging moods in Spot it can show if they follow your cycle.', 'NHS: PMS', 'draft', true, now()),
  ('mood-hormones-1-03', 'mood-hormones', 1, 'Oestrogen can affect serotonin, a brain chemical linked to mood.', 'fact', 'Hormones talk to your brain too.', 'Yep! When oestrogen rises and falls, it can nudge serotonin, which may be one reason moods change across the cycle.', 'Serotonin also helps with sleep and appetite.', 'Cleveland Clinic: Serotonin', 'draft', true, now()),
  ('mood-hormones-1-04', 'mood-hormones', 1, 'Only adults get PMS.', 'myth', 'When do periods start?', 'Nope! Anyone who has periods can get PMS, including teens.', 'PMS symptoms can change as you get older.', 'NHS: PMS', 'draft', true, now()),
  ('mood-hormones-1-05', 'mood-hormones', 1, 'Crying more easily before your period is a common PMS symptom.', 'fact', 'Is it common or rare?', 'Yep! Feeling teary, sensitive or low before a period is really common, and it usually eases once your period starts.', 'Be extra kind to yourself on those days.', 'NHS: PMS', 'draft', true, now()),
  ('mood-hormones-1-06', 'mood-hormones', 1, 'If you feel anxious, it’s always because of your period.', 'myth', 'Is there only one cause of worry?', 'Nope! Hormones can play a part, but worry has lots of causes, like school, friends and big changes.', 'Tracking can help you see what’s hormones and what’s life.', 'NHS Every Mind Matters', 'draft', true, now()),
  ('mood-hormones-1-07', 'mood-hormones', 1, 'Talking to someone you trust can make tough feelings easier to handle.', 'fact', 'A problem shared...', 'Yep! Saying how you feel out loud often makes it feel smaller and more manageable.', 'It can be a friend, family member, teacher or school nurse.', 'NHS Every Mind Matters', 'draft', true, now()),
  ('mood-hormones-1-08', 'mood-hormones', 1, 'Getting outside in daylight can give your mood a lift.', 'fact', 'Think sunshine.', 'Yep! Daylight and fresh air are simple mood boosters, even on a cloudy day.', 'Morning light helps your sleep too.', 'NHS Every Mind Matters', 'draft', true, now()),
  ('mood-hormones-1-09', 'mood-hormones', 1, 'Ignoring big feelings makes them go away faster.', 'myth', 'Do pushed-down feelings vanish?', 'Nope! Bottling feelings up can make them build. Naming them and talking about them helps them pass.', 'Even writing one sentence about how you feel can help.', 'NHS Every Mind Matters', 'draft', true, now()),
  ('mood-hormones-1-10', 'mood-hormones', 1, 'PMS mood changes usually ease once your period starts.', 'fact', 'Think about timing.', 'Yep! For most people, PMS symptoms fade within a few days of the period starting.', 'That timing is a big clue doctors use.', 'NHS: PMS', 'draft', true, now()),
  ('mood-hormones-2-01', 'mood-hormones', 2, 'Some people notice more energy and confidence in the days before ovulation.', 'fact', 'Oestrogen is climbing.', 'Yep! Rising oestrogen in the first half of the cycle can come with a lift in energy for some people.', 'Not everyone notices it, and that’s fine too.', 'Cleveland Clinic: Menstrual cycle', 'draft', true, now()),
  ('mood-hormones-2-02', 'mood-hormones', 2, 'The week before a period feels the same for everyone.', 'myth', 'Are any two cycles the same?', 'Nope! Some people barely notice it, while others feel big changes. Both are normal.', 'Your pattern is personal to you.', 'NHS: PMS', 'draft', true, now()),
  ('mood-hormones-2-03', 'mood-hormones', 2, 'Tracking your mood for a few months can show whether it follows your cycle.', 'fact', 'What do doctors ask for?', 'Yep! A symptom diary over two or three cycles is one of the best ways to spot PMS.', 'Spot it’s mood log is made for this.', 'NHS: PMS', 'draft', true, now()),
  ('mood-hormones-2-04', 'mood-hormones', 2, 'PMS symptoms start on the first day of your period.', 'myth', 'P-M-S. What does the P-M stand for?', 'Nope! The ‘pre’ in premenstrual means before. Symptoms show up in the days or weeks before your period.', 'They usually ease once bleeding starts.', 'NHS: PMS', 'draft', true, now()),
  ('mood-hormones-2-05', 'mood-hormones', 2, 'Irritability is one of the most common PMS symptoms.', 'fact', 'Snappy?', 'Yep! Feeling irritable or short-tempered is one of the most reported PMS symptoms.', 'A quick walk or a few slow breaths can take the edge off.', 'NHS: PMS', 'draft', true, now()),
  ('mood-hormones-2-06', 'mood-hormones', 2, 'Hormones only affect your body, not your thoughts or feelings.', 'myth', 'Where do hormones travel?', 'Nope! Hormones reach your brain too, so they can affect mood, focus and sleep.', 'Your brain has receptors for oestrogen and progesterone.', 'Cleveland Clinic: Hormones', 'draft', true, now()),
  ('mood-hormones-2-07', 'mood-hormones', 2, 'Feeling bloated or tired can make your mood dip too.', 'fact', 'Body and mind are connected.', 'Yep! Physical PMS symptoms like bloating and tiredness can drag your mood down with them.', 'Looking after your body helps your mood too.', 'NHS: PMS', 'draft', true, now()),
  ('mood-hormones-2-08', 'mood-hormones', 2, 'A bad mood before your period is just an excuse.', 'myth', 'Is PMS real?', 'Nope! PMS is a real, recognised condition. Your feelings are valid.', 'Doctors take PMS seriously and can help if it’s tough.', 'NHS: PMS', 'draft', true, now()),
  ('mood-hormones-2-09', 'mood-hormones', 2, 'Progesterone, which rises after ovulation, can make some people feel sleepier.', 'fact', 'Think of a cosy hormone.', 'Yep! Progesterone has a slightly calming effect, so some people feel more tired in the second half of their cycle.', 'Your body temperature rises a little at the same time.', 'Sleep Foundation: Sleep and the menstrual cycle', 'draft', true, now()),
  ('mood-hormones-2-10', 'mood-hormones', 2, 'Low mood that lasts most of the month, not just before your period, is worth talking to a doctor about.', 'fact', 'Is it timed with your cycle?', 'Yep! If low mood sticks around all month, it might not be PMS, and a doctor can help work out what’s going on.', 'You don’t need to wait until things feel really bad.', 'NHS: Depression in young people', 'draft', true, now()),
  ('mood-hormones-3-01', 'mood-hormones', 3, 'Even a 10-minute walk can boost your mood.', 'fact', 'Small moves count.', 'Yep! Short bursts of movement can lift your mood and ease stress.', 'Walking with a friend is a double win.', 'NHS Every Mind Matters', 'draft', true, now()),
  ('mood-hormones-3-02', 'mood-hormones', 3, 'Scrolling on your phone late at night helps you unwind.', 'myth', 'What does a bright screen tell your brain?', 'Nope! Late scrolling can keep your brain buzzing and push back sleep, which can make moods worse the next day.', 'Try putting the phone down an hour before bed.', 'NHS: Sleep tips for teens', 'draft', true, now()),
  ('mood-hormones-3-03', 'mood-hormones', 3, 'Writing your feelings down can help you make sense of them.', 'fact', 'Pen and paper power.', 'Yep! Journalling can help you notice patterns and feel calmer.', 'Spot it’s notes are a good place to start.', 'NHS Every Mind Matters', 'draft', true, now()),
  ('mood-hormones-3-04', 'mood-hormones', 3, 'Asking for help with your feelings means you’re weak.', 'myth', 'Do strong people ask for help?', 'Nope! Asking for help takes courage, and it’s one of the best things you can do for yourself.', 'Lots of people feel better once they’ve talked to someone.', 'NHS Every Mind Matters', 'draft', true, now()),
  ('mood-hormones-3-05', 'mood-hormones', 3, 'Breathing out for longer than you breathe in can help calm your body down.', 'fact', 'Slow it down.', 'Yep! Long, slow out-breaths tell your nervous system it’s OK to relax.', 'Try breathing in for 4 and out for 6.', 'NHS: Breathing exercises for stress', 'draft', true, now()),
  ('mood-hormones-3-06', 'mood-hormones', 3, 'If feelings ever get too much, or you think about hurting yourself, you should reach out for help straight away.', 'fact', 'You deserve support.', 'Yes. Talk to a trusted adult or a doctor, or call a helpline. In an emergency, call your local emergency number.', 'You are never a burden for asking for help.', 'NHS: Get help for suicidal thoughts', 'draft', true, now()),
  ('mood-hormones-3-07', 'mood-hormones', 3, 'Sugary snacks are the best fix for a low mood.', 'myth', 'Quick lift, then...?', 'Nope! Sugar can give a quick lift, then a slump. Regular meals, sleep and movement are better for steady moods.', 'A treat is fine, it just isn’t a mood fix.', 'NHS: Eat well', 'draft', true, now()),
  ('mood-hormones-3-08', 'mood-hormones', 3, 'Getting enough sleep makes stress easier to handle.', 'fact', 'Ever felt everything is worse when you’re tired?', 'Yep! Sleep helps your brain manage emotions, so good sleep makes tough days easier.', 'Teens need about 8 to 10 hours a night.', 'NHS: Sleep tips for teens', 'draft', true, now()),
  ('mood-hormones-3-09', 'mood-hormones', 3, 'You have to wait until things are really bad before talking to a school nurse or doctor.', 'myth', 'Is there a minimum?', 'Nope! You can ask for help with your feelings at any time. Early support often helps most.', 'School nurses hear about feelings all the time.', 'NHS Every Mind Matters', 'draft', true, now()),
  ('mood-hormones-3-10', 'mood-hormones', 3, 'Doing something you enjoy, like music or drawing, counts as looking after your mental health.', 'fact', 'Fun counts.', 'Yep! Hobbies give your mind a break and can really lift your mood.', 'Even 15 minutes a day of something you love helps.', 'NHS Every Mind Matters', 'draft', true, now()),
  ('sleep-cycle-1-01', 'sleep-cycle', 1, 'Teenagers need about 8 to 10 hours of sleep a night.', 'fact', 'More than adults.', 'Yep! Teens need more sleep than adults because their bodies and brains are still growing.', 'Most teens get less than this on school nights.', 'American Academy of Sleep Medicine: Sleep needs', 'draft', true, now()),
  ('sleep-cycle-1-02', 'sleep-cycle', 1, 'You can fully catch up on a week of lost sleep with one big lie-in.', 'myth', 'Can you pay it all back in one go?', 'Nope! A lie-in helps a bit, but it can’t fully undo a week of short nights, and it can mess with your body clock.', 'Regular sleep beats catch-up sleep.', 'Sleep Foundation: Sleep debt', 'draft', true, now()),
  ('sleep-cycle-1-03', 'sleep-cycle', 1, 'Your body has a built-in 24-hour clock called your circadian rhythm.', 'fact', 'Tick tock.', 'Yep! It controls when you feel sleepy and alert, and it’s set mainly by light.', '‘Circadian’ comes from Latin for ‘about a day’.', 'Sleep Foundation: Circadian rhythm', 'draft', true, now()),
  ('sleep-cycle-1-04', 'sleep-cycle', 1, 'Teen body clocks naturally shift later, so feeling sleepy later at night is normal.', 'fact', 'Night owl phase?', 'Yep! In the teen years, your body releases its sleep hormone later, so you feel sleepy later.', 'This shift usually eases in your twenties.', 'Sleep Foundation: Teens and sleep', 'draft', true, now()),
  ('sleep-cycle-1-05', 'sleep-cycle', 1, 'Light from screens has no effect on sleep.', 'myth', 'What does light tell your brain?', 'Nope! Bright screen light at night can tell your brain it’s still daytime and make it harder to fall asleep.', 'Night mode helps a little, but putting the phone away helps more.', 'Sleep Foundation: Screens and sleep', 'draft', true, now()),
  ('sleep-cycle-1-06', 'sleep-cycle', 1, 'Melatonin is the hormone that tells your body it’s time to sleep.', 'fact', 'It comes out in the dark.', 'Yep! Your brain releases melatonin as it gets dark, helping you feel sleepy.', 'Light, especially bright light, slows melatonin down.', 'Sleep Foundation: Melatonin', 'draft', true, now()),
  ('sleep-cycle-1-07', 'sleep-cycle', 1, 'Everyone needs exactly 8 hours of sleep, no more, no less.', 'myth', 'Is there a magic number?', 'Nope! Sleep needs vary with age and from person to person. Teens usually need 8 to 10.', 'Waking up refreshed is a good sign you’re getting enough.', 'American Academy of Sleep Medicine: Sleep needs', 'draft', true, now()),
  ('sleep-cycle-1-08', 'sleep-cycle', 1, 'Most vivid dreams happen during REM sleep.', 'fact', 'R-E-M stands for rapid eye...', 'Yep! REM stands for rapid eye movement, and it’s when the most vivid dreams usually happen.', 'Your eyes really do dart around under your eyelids.', 'Sleep Foundation: Stages of sleep', 'draft', true, now()),
  ('sleep-cycle-1-09', 'sleep-cycle', 1, 'A can of cola in the evening won’t affect your sleep.', 'myth', 'What’s in cola?', 'Nope! Cola contains caffeine, which can keep you awake for hours.', 'Some iced teas and chocolate contain caffeine too.', 'NHS: Sleep tips for teens', 'draft', true, now()),
  ('sleep-cycle-1-10', 'sleep-cycle', 1, 'Not getting enough sleep can make it harder to concentrate at school.', 'fact', 'Ever had a foggy morning?', 'Yep! Sleep helps your brain store what you learned and stay focused.', 'Sleep is when your brain files away the day’s memories.', 'NHS: Sleep tips for teens', 'draft', true, now()),
  ('sleep-cycle-2-01', 'sleep-cycle', 2, 'Some people sleep worse in the few days before their period.', 'fact', 'Hormones are on the move.', 'Yep! Falling hormone levels before a period can make sleep lighter or more broken for some people.', 'Logging sleep and your cycle together can show if this is you.', 'Sleep Foundation: Sleep and the menstrual cycle', 'draft', true, now()),
  ('sleep-cycle-2-02', 'sleep-cycle', 2, 'Your body temperature is a little higher after ovulation, which can make sleep feel lighter.', 'fact', 'Progesterone warms you up.', 'Yep! After ovulation, progesterone nudges your temperature up a bit, and a warmer body can sleep less deeply.', 'A cooler bedroom can help.', 'Sleep Foundation: Sleep and the menstrual cycle', 'draft', true, now()),
  ('sleep-cycle-2-03', 'sleep-cycle', 2, 'Period cramps can’t wake you up.', 'myth', 'Can pain interrupt sleep?', 'Nope! Cramps can wake people up or make it hard to drift off. A hot water bottle or a painkiller before bed can help.', 'Lying curled on your side eases cramps for some.', 'Sleep Foundation: Sleep and the menstrual cycle', 'draft', true, now()),
  ('sleep-cycle-2-04', 'sleep-cycle', 2, 'Sleeping on your side with your knees tucked up can ease cramps for some people.', 'fact', 'Curl up.', 'Yep! This position takes pressure off your tummy muscles, which some people find comfier during cramps.', 'Some people call it the foetal position.', 'Sleep Foundation: Sleep and the menstrual cycle', 'draft', true, now()),
  ('sleep-cycle-2-05', 'sleep-cycle', 2, 'Feeling extra tired on your period is always a sign of something serious.', 'myth', 'Is it common?', 'Nope! Feeling more tired on your period is common. But if you’re wiped out all the time, check your iron with a doctor.', 'Heavy periods are a common reason for low iron.', 'NHS: Iron deficiency anaemia', 'draft', true, now()),
  ('sleep-cycle-2-06', 'sleep-cycle', 2, 'Low iron from heavy periods can leave you tired even after a full night’s sleep.', 'fact', 'Iron carries oxygen.', 'Yep! Without enough iron, your blood carries less oxygen, so you can feel tired no matter how much you sleep.', 'A simple blood test can check your iron.', 'NHS: Iron deficiency anaemia', 'draft', true, now()),
  ('sleep-cycle-2-07', 'sleep-cycle', 2, 'Night sweats only happen to older women.', 'myth', 'Can hormones change at any age?', 'Nope! Some people get night sweats around their period because of hormone changes. They’re also linked to menopause, illness and some medicines.', 'Breathable bedding can help.', 'Sleep Foundation: Sleep and the menstrual cycle', 'draft', true, now()),
  ('sleep-cycle-2-08', 'sleep-cycle', 2, 'A cool bedroom can help you sleep, especially in the second half of your cycle.', 'fact', 'Remember the temperature rise?', 'Yep! Your body needs to cool down to fall asleep, and that can be harder when progesterone is high.', 'Around 16 to 18°C suits most people.', 'Sleep Foundation: Sleep and the menstrual cycle', 'draft', true, now()),
  ('sleep-cycle-2-09', 'sleep-cycle', 2, 'Napping for hours in the afternoon helps you sleep better at night.', 'myth', 'What happens to your sleepiness?', 'Nope! Long naps late in the day can make it harder to fall asleep at night. Keep naps short and early.', 'Around 20 minutes is a good power nap.', 'Sleep Foundation: Napping', 'draft', true, now()),
  ('sleep-cycle-2-10', 'sleep-cycle', 2, 'Tracking your sleep alongside your cycle can help you spot patterns.', 'fact', 'Data is your friend.', 'Yep! You might notice certain days in your cycle when sleep is harder, so you can plan for them.', 'Spot it can show your logs on the calendar.', 'Sleep Foundation: Sleep and the menstrual cycle', 'draft', true, now()),
  ('sleep-cycle-3-01', 'sleep-cycle', 3, 'Going to bed and waking up at the same times, even at weekends, helps your body clock.', 'fact', 'Body clocks love routine.', 'Yep! A steady routine trains your body clock, so falling asleep and waking up get easier.', 'Even keeping weekends within an hour or so helps.', 'NHS: Sleep tips for teens', 'draft', true, now()),
  ('sleep-cycle-3-02', 'sleep-cycle', 3, 'Exercising during the day makes it harder to sleep.', 'myth', 'Tired muscles?', 'Nope! Regular exercise usually helps you sleep better. Just avoid hard workouts right before bed.', 'Morning or afternoon movement is ideal.', 'Sleep Foundation: Exercise and sleep', 'draft', true, now()),
  ('sleep-cycle-3-03', 'sleep-cycle', 3, 'Putting screens away about an hour before bed can help you fall asleep.', 'fact', 'Wind-down time.', 'Yep! Less light and less scrolling give your brain time to switch off.', 'Try a book, music or a podcast instead.', 'NHS: Sleep tips for teens', 'draft', true, now()),
  ('sleep-cycle-3-04', 'sleep-cycle', 3, 'If you can’t sleep, staying in bed and trying harder is the best thing to do.', 'myth', 'Does trying harder to sleep work?', 'Nope! If you can’t sleep after about 20 minutes, get up and do something calm in dim light, then go back when you feel sleepy.', 'This stops your brain linking bed with lying awake.', 'NHS: Insomnia', 'draft', true, now()),
  ('sleep-cycle-3-05', 'sleep-cycle', 3, 'Morning daylight helps reset your body clock.', 'fact', 'Sunlight sets the clock.', 'Yep! Bright light in the morning tells your body clock it’s daytime, helping you feel sleepy at the right time later.', 'Even 10 to 15 minutes outside helps.', 'Sleep Foundation: Light and sleep', 'draft', true, now()),
  ('sleep-cycle-3-06', 'sleep-cycle', 3, 'Energy drinks are a safe fix for feeling tired.', 'myth', 'What’s in them?', 'Nope! Energy drinks are packed with caffeine and sugar and aren’t recommended for children and teens.', 'In the UK, many shops don’t sell them to under-16s.', 'NHS: Energy drinks', 'draft', true, now()),
  ('sleep-cycle-3-07', 'sleep-cycle', 3, 'A warm, not hot, bath an hour or two before bed can help you feel sleepy.', 'fact', 'Warm up to cool down.', 'Yep! Your body cools down after a warm bath, and that cooling helps trigger sleep.', 'Too hot or too close to bedtime can have the opposite effect.', 'Sleep Foundation: Bathing and sleep', 'draft', true, now()),
  ('sleep-cycle-3-08', 'sleep-cycle', 3, 'Snoring is always harmless.', 'myth', 'Is it ‘always’?', 'Nope! Snoring is often harmless, but loud snoring with gasping or pauses in breathing should be checked by a doctor.', 'This can be a sign of sleep apnoea.', 'NHS: Snoring', 'draft', true, now()),
  ('sleep-cycle-3-09', 'sleep-cycle', 3, 'Struggling to sleep for weeks is worth talking to a doctor about.', 'fact', 'When does it become a problem?', 'Yep! If poor sleep goes on for weeks and affects your day, a doctor can help work out why.', 'There are good treatments that don’t involve sleeping pills.', 'NHS: Insomnia', 'draft', true, now()),
  ('sleep-cycle-3-10', 'sleep-cycle', 3, 'Writing a quick to-do list before bed can help quiet a busy mind.', 'fact', 'Brain dump.', 'Yep! Getting tomorrow’s jobs onto paper can stop them going round your head at bedtime.', 'A study found people who wrote to-do lists fell asleep faster.', 'Sleep Foundation: Bedtime routine', 'draft', true, now()),
  ('my-cycle-4-01', 'my-cycle', 4, 'Sperm can survive inside the body for up to 5 days, so the fertile window starts before ovulation.', 'fact', 'Who arrives early to the party?', 'Correct! Because sperm can wait for up to 5 days, the fertile window is the 5 days before ovulation plus ovulation day.', 'That’s about 6 fertile days per cycle.', 'NHS: Ovulation and fertility', 'draft', true, now()),
  ('my-cycle-4-02', 'my-cycle', 4, 'Your cervix changes position and feel across your cycle.', 'fact', 'Is your body static?', 'Correct! Around ovulation the cervix tends to sit higher and feel softer, then lower and firmer afterwards.', 'Some people track this as a fertility sign.', 'Cleveland Clinic: Menstrual cycle', 'draft', true, now()),
  ('my-cycle-4-03', 'my-cycle', 4, 'The womb lining can grow several times thicker between the end of your period and ovulation.', 'fact', 'Oestrogen is a builder.', 'Correct! Rising oestrogen builds the lining up from very thin after a period to many times thicker.', 'Doctors can measure the lining on an ultrasound.', 'Cleveland Clinic: Menstrual cycle', 'draft', true, now()),
  ('my-cycle-4-04', 'my-cycle', 4, 'The hormone surge that triggers ovulation comes from the ovaries.', 'myth', 'Which gland sends the ‘go’ signal?', 'Wrong one! The LH surge comes from the pituitary gland in your brain. The ovaries respond to it.', 'The pituitary is about the size of a pea.', 'Cleveland Clinic: Luteinizing hormone', 'draft', true, now()),
  ('my-cycle-4-05', 'my-cycle', 4, 'After ovulation, the empty follicle becomes the corpus luteum, which makes progesterone.', 'fact', 'Leftovers with a job.', 'Correct! The empty follicle turns into a temporary gland that pumps out progesterone.', 'Corpus luteum means ‘yellow body’ in Latin.', 'ACOG: Your menstrual cycle', 'draft', true, now()),
  ('my-cycle-4-06', 'my-cycle', 4, 'If you don’t ovulate in a cycle, you can’t have any bleeding.', 'myth', 'Is every bleed a true period?', 'Not true! Bleeding can still happen without ovulation. It’s called an anovulatory bleed, and it’s common in the first few years of periods.', 'It’s also common around perimenopause.', 'Cleveland Clinic: Menstrual cycle', 'draft', true, now()),
  ('my-cycle-4-07', 'my-cycle', 4, 'Your resting body temperature rises by roughly 0.2 to 0.5°C after ovulation.', 'fact', 'Progesterone is a heater.', 'Correct! Progesterone nudges your resting temperature up slightly, and it stays up until your next period.', 'Some people track this every morning as a fertility sign.', 'NHS: Ovulation and fertility', 'draft', true, now()),
  ('my-cycle-4-08', 'my-cycle', 4, 'Ovulation tests detect oestrogen in your pee.', 'myth', 'Which hormone surges?', 'Not quite! Most ovulation tests detect the LH surge, which comes 1 to 2 days before ovulation.', 'Some newer tests also check an oestrogen marker.', 'Cleveland Clinic: Ovulation', 'draft', true, now()),
  ('my-cycle-4-09', 'my-cycle', 4, 'Chemicals called prostaglandins, released by the womb lining, make the womb contract during your period.', 'fact', 'What makes the squeeze?', 'Correct! Prostaglandins make the womb muscles tighten. More prostaglandins can mean stronger cramps.', 'Ibuprofen works by lowering prostaglandins.', 'ACOG: Dysmenorrhea', 'draft', true, now()),
  ('my-cycle-4-10', 'my-cycle', 4, 'Your ovaries make brand-new eggs every month.', 'myth', 'Is the supply topped up?', 'Not true! You’re born with all the immature eggs you’ll ever have. Each cycle, a few start to grow.', 'Your eggs formed before you were even born.', 'ACOG: Your menstrual cycle', 'draft', true, now()),
  ('my-cycle-5-01', 'my-cycle', 5, 'Out of 1 to 2 million eggs at birth, only around 400 to 500 will ever be released.', 'fact', 'Most never get the call.', 'Correct! The rest naturally fade away over time. Only a few hundred are ever ovulated.', 'That’s roughly one egg for each cycle in your life.', 'ACOG: Your menstrual cycle', 'draft', true, now()),
  ('my-cycle-5-02', 'my-cycle', 5, 'By puberty, you still have about the same number of eggs you were born with.', 'myth', 'Does the number shrink?', 'Not true! By puberty there are only about 300,000 to 400,000 left.', 'Eggs are lost naturally all through childhood.', 'ACOG: Your menstrual cycle', 'draft', true, now()),
  ('my-cycle-5-03', 'my-cycle', 5, 'The LH surge usually happens about 24 to 36 hours before ovulation.', 'fact', 'Is it the same moment?', 'Correct! The egg is usually released a day or so after the LH surge starts.', 'That’s why a positive ovulation test means ‘soon’, not ‘now’.', 'Cleveland Clinic: Luteinizing hormone', 'draft', true, now()),
  ('my-cycle-5-04', 'my-cycle', 5, 'Around ovulation, cervical mucus is thick and sticky to block sperm.', 'myth', 'Think egg white.', 'Backwards! Around ovulation it’s thin, clear and stretchy to help sperm travel. It thickens after ovulation.', 'Progesterone is what makes it thick again.', 'Cleveland Clinic: Cervical mucus', 'draft', true, now()),
  ('my-cycle-5-05', 'my-cycle', 5, 'Several follicles start growing each cycle, but usually only one becomes the dominant follicle that releases an egg.', 'fact', 'Only one wins.', 'Correct! One follicle pulls ahead and the others stop growing.', 'When two win, non-identical twins can happen.', 'ACOG: Your menstrual cycle', 'draft', true, now()),
  ('my-cycle-5-06', 'my-cycle', 5, 'If the luteal phase is short, the follicular phase must be long to make up for it.', 'myth', 'Are the two halves linked?', 'Not true! The two phases aren’t balanced against each other. Cycle length varies mostly because of the follicular phase.', 'A short luteal phase can be a sign of low progesterone.', 'Cleveland Clinic: Menstrual cycle', 'draft', true, now()),
  ('my-cycle-5-07', 'my-cycle', 5, 'In a study of more than 600,000 cycles, only about 13% were exactly 28 days long.', 'fact', 'Is 28 the norm?', 'Correct! A big study using app data found most cycles weren’t 28 days, and the average was about 29.', 'The study used data from over 120,000 people.', 'Bull et al., npj Digital Medicine (2019)', 'draft', true, now()),
  ('my-cycle-5-08', 'my-cycle', 5, 'The corpus luteum keeps making progesterone for the rest of the cycle no matter what.', 'myth', 'What happens if there’s no pregnancy?', 'Not true! Without a pregnancy it breaks down after about 10 to 14 days. Progesterone falls and a period starts.', 'If there is a pregnancy, hCG keeps it going.', 'ACOG: Your menstrual cycle', 'draft', true, now()),
  ('my-cycle-5-09', 'my-cycle', 5, 'In early pregnancy, the hormone hCG keeps the corpus luteum making progesterone.', 'fact', 'Pregnancy tests look for it.', 'Correct! hCG tells the corpus luteum to keep going until the placenta takes over.', 'Home pregnancy tests detect hCG in pee.', 'Cleveland Clinic: hCG', 'draft', true, now()),
  ('my-cycle-5-10', 'my-cycle', 5, 'Spotting around ovulation happens because the egg tears through the ovary and bleeds out.', 'myth', 'Think about hormone levels.', 'Not quite! Mid-cycle spotting is thought to be caused by the brief dip in oestrogen around ovulation, not by bleeding from the ovary.', 'Only a small number of people notice ovulation spotting.', 'Cleveland Clinic: Menstrual cycle', 'draft', true, now()),
  ('period-myths-4-01', 'period-myths', 4, 'In some places, girls miss school because they don’t have period products or safe toilets.', 'fact', 'Is this just a far-away problem?', 'Correct! Period poverty affects girls worldwide, including in wealthy countries.', 'Free period product schemes now run in many schools.', 'UNICEF: Menstrual hygiene', 'draft', true, now()),
  ('period-myths-4-02', 'period-myths', 4, 'Using a tampon or cup stretches your vagina permanently.', 'myth', 'How stretchy is the vagina?', 'Not true! The vagina is very elastic and returns to its usual shape.', 'The vaginal walls have folds called rugae that let it stretch and recover.', 'Cleveland Clinic: Vagina', 'draft', true, now()),
  ('period-myths-4-03', 'period-myths', 4, 'The word ‘hysteria’ comes from the Greek word for womb.', 'fact', 'Hyster-ectomy?', 'Correct! It comes from ‘hystera’, meaning womb. Ancient doctors wrongly blamed many illnesses on the womb.', 'It’s a reminder of how old some period myths are.', 'Merriam-Webster: Hysteria', 'draft', true, now()),
  ('period-myths-4-04', 'period-myths', 4, 'Toxic shock syndrome is so common that most tampon users will get it.', 'myth', 'How rare is rare?', 'Not true! TSS is very rare. Using the lowest absorbency you need and changing regularly keeps the risk low.', 'Most tampon users will never meet TSS.', 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('period-myths-4-05', 'period-myths', 4, 'Period pain without an underlying condition usually starts within a year or two of a first period.', 'fact', 'When does it begin?', 'Correct! This is called primary dysmenorrhoea. It often starts once periods become regular.', 'Pain that starts later in life is more likely to have another cause.', 'ACOG: Dysmenorrhea', 'draft', true, now()),
  ('period-myths-4-06', 'period-myths', 4, 'Doctors can tell whether someone is a virgin by looking at their hymen.', 'myth', 'Ask the WHO.', 'Not true! Hymens vary hugely, and the World Health Organization says ‘virginity testing’ has no scientific basis.', 'Many hymens naturally have openings and stretch without tearing.', 'WHO: Eliminating virginity testing', 'draft', true, now()),
  ('period-myths-4-07', 'period-myths', 4, 'Menstrual fluid isn’t all blood. It also contains womb lining, mucus and other fluid.', 'fact', 'What’s being shed?', 'Correct! Period fluid is a mix of blood, tissue from the womb lining and mucus.', 'That’s why it can look thicker than ordinary blood.', 'Cleveland Clinic: Menstruation', 'draft', true, now()),
  ('period-myths-4-08', 'period-myths', 4, 'Missing a period always means something is wrong.', 'myth', 'What else can delay a period?', 'Not always! Stress, illness, travel, weight changes and being in your first years of periods can all delay one. Missing 3 or more is worth checking.', 'Spot it can show if a period is late compared to your usual.', 'NHS: Stopped or missed periods', 'draft', true, now()),
  ('period-myths-4-09', 'period-myths', 4, 'Lots of intense training without eating enough can make periods stop.', 'fact', 'Energy in, energy out.', 'Correct! When the body doesn’t have enough energy, it can switch off periods to save fuel. This can weaken bones.', 'Doctors call this RED-S, relative energy deficiency in sport.', 'NHS: Stopped or missed periods', 'draft', true, now()),
  ('period-myths-4-10', 'period-myths', 4, 'PMS was first described in the 1990s.', 'myth', 'Older than your parents?', 'Way earlier! A doctor described ‘premenstrual tension’ in 1931, and people noticed it long before then.', 'Ancient Greek writers described symptoms before periods too.', 'Frank, Archives of Neurology and Psychiatry (1931)', 'draft', true, now()),
  ('period-myths-5-01', 'period-myths', 5, 'Big studies using app data have found no good evidence that periods sync up.', 'fact', 'Data vs stories.', 'Correct! Studies of people living together found cycles don’t sync. Apparent syncing is usually coincidence.', 'With cycles of different lengths, overlaps happen by chance.', 'Yang and Schank, Human Nature (2006)', 'draft', true, now()),
  ('period-myths-5-02', 'period-myths', 5, 'Menstrual cups were invented in the 2000s.', 'myth', 'Older than you think.', 'Way older! Menstrual cups were patented in the 1930s.', 'Leona Chalmers patented an early cup in 1937.', 'Smithsonian: History of menstrual products', 'draft', true, now()),
  ('period-myths-5-03', 'period-myths', 5, 'Early disposable pads were inspired by bandage material used by nurses in the First World War.', 'fact', 'Hospital supply cupboard.', 'Correct! Nurses noticed how absorbent the wartime material was, and it led to one of the first commercial pads.', 'Before that, many people used washable cloth.', 'Smithsonian: History of menstrual products', 'draft', true, now()),
  ('period-myths-5-04', 'period-myths', 5, 'TSS happens because the tampon material itself is poisonous.', 'myth', 'Who makes the toxin?', 'Not true! TSS is caused by toxins from certain bacteria, like Staphylococcus aureus. The tampon is not the poison.', 'TSS can also happen after skin wounds or burns.', 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('period-myths-5-05', 'period-myths', 5, 'Toxic shock syndrome can also happen with menstrual cups, though it’s very rare.', 'fact', 'Is any internal product zero risk?', 'Correct! TSS is extremely rare with cups, but cases have been reported. Clean and empty your cup as directed.', 'Washing hands before inserting helps.', 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('period-myths-5-06', 'period-myths', 5, 'Doctors have long used 80 ml per period as the cut-off for ‘heavy’.', 'fact', 'Measured in millilitres.', 'Correct! Over 80 ml was the classic definition. Today doctors focus more on how much periods affect your life.', 'A typical period loses about 30 to 40 ml.', 'NHS: Heavy periods', 'draft', true, now()),
  ('period-myths-5-07', 'period-myths', 5, 'Dark or brown period blood means it’s toxic.', 'myth', 'What does oxygen do to blood?', 'Not true! Darker blood is just older blood that has met more oxygen. It’s usually normal.', 'Brown is common at the start and end of a period.', 'Cleveland Clinic: Period blood colour', 'draft', true, now()),
  ('period-myths-5-08', 'period-myths', 5, 'Scotland was the first country in the world to pass a law making period products free for anyone who needs them.', 'fact', 'A world first.', 'Correct! Scotland passed the Period Products Act in 2020.', 'Products are free in places like schools, colleges and community centres.', 'Scottish Government: Period Products Act', 'draft', true, now()),
  ('period-myths-5-09', 'period-myths', 5, 'Over a lifetime, the average person has around 400 to 500 periods.', 'fact', 'Do the maths.', 'Correct! With periods from the early teens to the early fifties, it adds up to around 400 to 500.', 'That’s years of periods, which is why comfortable products matter.', 'ACOG: Your menstrual cycle', 'draft', true, now()),
  ('period-myths-5-10', 'period-myths', 5, 'Cramps are caused by the womb lining tearing off the womb wall.', 'myth', 'Squeeze or tear?', 'Not quite! Cramps come from the womb muscle contracting, driven by prostaglandins. The lining sheds gently.', 'Strong contractions can briefly reduce blood flow, which adds to the ache.', 'ACOG: Dysmenorrhea', 'draft', true, now()),
  ('body-changes-4-01', 'body-changes', 4, 'Thelarche is the medical name for the start of breast development.', 'fact', 'Greek words again.', 'Correct! Thelarche is usually the first visible sign of puberty in girls.', '‘Thele’ is Greek for nipple.', 'Nemours KidsHealth: Puberty', 'draft', true, now()),
  ('body-changes-4-02', 'body-changes', 4, 'First periods usually arrive about 2 to 3 years after breasts start developing.', 'fact', 'Think timeline.', 'Correct! Breast buds usually come first, and menarche follows a couple of years later.', 'That’s why breast buds are a good early clue.', 'ACOG: Menstruation in girls and adolescents', 'draft', true, now()),
  ('body-changes-4-03', 'body-changes', 4, 'In girls, the fastest growth spurt usually happens after the first period.', 'myth', 'Before or after?', 'Not true! The peak growth spurt usually comes before the first period. Growth slows afterwards.', 'Most girls grow only a few more centimetres after periods start.', 'Nemours KidsHealth: Puberty', 'draft', true, now()),
  ('body-changes-4-04', 'body-changes', 4, 'Growth plates at the ends of long bones close after puberty, and that’s when you stop getting taller.', 'fact', 'Bones have a finish line.', 'Correct! Once growth plates fuse, bones can’t get any longer.', 'X-rays can show whether growth plates are still open.', 'Nemours KidsHealth: Growth plates', 'draft', true, now()),
  ('body-changes-4-05', 'body-changes', 4, 'Oestrogen has nothing to do with when you stop growing.', 'myth', 'Which hormone closes growth plates?', 'Not true! Oestrogen is the main hormone that closes growth plates, in boys too.', 'That’s why earlier puberty can mean a shorter final height.', 'Endocrine Society: Puberty', 'draft', true, now()),
  ('body-changes-4-06', 'body-changes', 4, 'Signs of puberty before age 8 in girls should be checked by a doctor.', 'fact', 'Too early?', 'Correct! This is called early, or precocious, puberty, and doctors can check what’s causing it.', 'Treatment can pause puberty if needed.', 'NHS: Early or delayed puberty', 'draft', true, now()),
  ('body-changes-4-07', 'body-changes', 4, 'No breast development by 13 means you’re just a late bloomer, and nothing needs checking.', 'myth', 'When should a doctor take a look?', 'Not quite! If there are no signs of puberty by 13, it’s worth seeing a doctor. Usually all is fine, but it’s good to check.', 'Late puberty often runs in families.', 'NHS: Early or delayed puberty', 'draft', true, now()),
  ('body-changes-4-08', 'body-changes', 4, 'Doctors use ‘Tanner stages’, from 1 to 5, to describe how far along puberty is.', 'fact', 'Five steps.', 'Correct! Tanner stages track breast and pubic hair development from childhood to adult.', 'They’re named after the British doctor James Tanner.', 'Nemours KidsHealth: Puberty', 'draft', true, now()),
  ('body-changes-4-09', 'body-changes', 4, 'The average age for a first period in the UK and US is about 15.', 'myth', 'Earlier or later?', 'Earlier! The average is around 12, with anything from about 9 to 15 being common.', 'Some start at 8 and some at 16.', 'NHS: Periods', 'draft', true, now()),
  ('body-changes-4-10', 'body-changes', 4, 'Pubic and underarm hair are mainly caused by androgens from the adrenal glands.', 'fact', 'Glands above the kidneys.', 'Correct! The adrenal glands release androgens that kick-start body hair and body odour.', 'This stage is called adrenarche.', 'Endocrine Society: Puberty', 'draft', true, now()),
  ('body-changes-5-01', 'body-changes', 5, 'Puberty is switched on when the brain starts releasing a hormone called GnRH in pulses.', 'fact', 'Pulse, not steady flow.', 'Correct! Pulses of GnRH tell the pituitary to release LH and FSH, which wake up the ovaries.', 'A steady flow of GnRH would actually switch the system off.', 'Endocrine Society: Puberty', 'draft', true, now()),
  ('body-changes-5-02', 'body-changes', 5, 'Puberty starts in the ovaries, which then tell the brain what to do.', 'myth', 'Who’s the boss?', 'Backwards! Puberty starts in the brain, which signals the pituitary, which signals the ovaries.', 'This chain is called the HPO axis.', 'Endocrine Society: Puberty', 'draft', true, now()),
  ('body-changes-5-03', 'body-changes', 5, 'Leptin, a hormone made by body fat, helps tell the brain there’s enough energy for puberty.', 'fact', 'Fuel gauge.', 'Correct! Leptin acts like a fuel gauge, which is one reason very low body fat can delay periods.', 'Leptin also helps control appetite.', 'Endocrine Society: Puberty', 'draft', true, now()),
  ('body-changes-5-04', 'body-changes', 5, 'The average age of first periods has gone up over the last 150 years.', 'myth', 'Better food, earlier puberty?', 'Not true! It has dropped, mostly thanks to better nutrition and health.', 'In the 1800s, first periods often came at 16 or 17.', 'ACOG: Menstruation in girls and adolescents', 'draft', true, now()),
  ('body-changes-5-05', 'body-changes', 5, 'Adrenarche, when the adrenal glands start making more androgens, can begin around age 6 to 8.', 'fact', 'Earlier than breasts.', 'Correct! It often starts years before breast development, though it’s not visible at first.', 'It’s behind the first body odour.', 'Endocrine Society: Puberty', 'draft', true, now()),
  ('body-changes-5-06', 'body-changes', 5, 'Healthy vaginal fluid is slightly alkaline, like soap.', 'myth', 'Acid or alkali?', 'Not true! A healthy vagina is acidic, usually around pH 3.8 to 4.5. That helps keep infections away.', 'That’s one reason soap inside the vagina is a bad idea.', 'Cleveland Clinic: Vaginal pH', 'draft', true, now()),
  ('body-changes-5-07', 'body-changes', 5, 'Good bacteria called lactobacilli help keep the vagina acidic and healthy.', 'fact', 'Friendly bugs.', 'Correct! Lactobacilli make lactic acid, which keeps the pH low and harmful bugs away.', 'They’re related to the bacteria in yoghurt.', 'Cleveland Clinic: Vaginal pH', 'draft', true, now()),
  ('body-changes-5-08', 'body-changes', 5, 'The teenage brain finishes developing by about 16.', 'myth', 'Longer than you think.', 'Not true! The brain keeps developing into the mid-twenties, especially the areas for planning and decisions.', 'The front of the brain is the last to finish.', 'NIMH: The teen brain', 'draft', true, now()),
  ('body-changes-5-09', 'body-changes', 5, 'Most of your adult bone mass is built by your late teens.', 'fact', 'Bone bank.', 'Correct! About 90% of peak bone mass is built by around age 18 to 20, so the teen years matter.', 'Calcium, vitamin D and exercise all help.', 'NIH: Kids and their bones', 'draft', true, now()),
  ('body-changes-5-10', 'body-changes', 5, 'Stretch marks happen because skin cells die.', 'myth', 'What stretches?', 'Not quite! Stretch marks form when the deeper layer of skin stretches quickly and its collagen and elastic fibres tear.', 'They often fade to silver or pale over time.', 'NHS: Stretch marks', 'draft', true, now()),
  ('period-care-4-01', 'period-care', 4, 'Tampons are labelled by absorbency, and ‘light’ holds less than about 6 grams of fluid.', 'fact', 'Grams, not ml.', 'Correct! Standard labels go light, regular, super and super plus, each holding a bit more.', 'The labels are standard so you can compare brands.', 'FDA: The facts on tampons', 'draft', true, now()),
  ('period-care-4-02', 'period-care', 4, 'Menstrual cups hold less than a tampon.', 'myth', 'Compare a cup and a tampon.', 'Not true! Many cups hold about 20 to 30 ml, more than most tampons.', 'That’s why cups can often stay in longer.', 'Cleveland Clinic: Menstrual cups', 'draft', true, now()),
  ('period-care-4-03', 'period-care', 4, 'Early TSS can look like flu: high fever, being sick, a sunburn-like rash and dizziness.', 'fact', 'Sneaky symptoms.', 'Correct! If you have these while using a tampon or cup, remove it and get urgent help.', 'TSS is rare but serious, so act fast.', 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('period-care-4-04', 'period-care', 4, 'If you think you have TSS, keep the tampon in so the doctor can see it.', 'myth', 'Remove or keep?', 'Not true! Take it out straight away and get urgent medical help. Tell the doctor you were using one.', 'Quick treatment makes a big difference.', 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('period-care-4-05', 'period-care', 4, 'Boiling a menstrual cup for a few minutes between periods is a common way to clean it.', 'fact', 'Hot water to the rescue.', 'Correct! Many brands suggest boiling between periods and rinsing in between changes. Always follow your cup’s instructions.', 'Some people use a separate pan just for the cup.', 'Cleveland Clinic: Menstrual cups', 'draft', true, now()),
  ('period-care-4-06', 'period-care', 4, 'Period pants need a hot wash with fabric softener to work properly.', 'myth', 'What does softener do to absorbent fabric?', 'Not true! Most brands say rinse in cold water, wash cool and skip softener, because it can block the absorbent layers.', 'Air-drying helps them last longer.', 'Which?: Period pants care', 'draft', true, now()),
  ('period-care-4-07', 'period-care', 4, 'Ibuprofen and naproxen ease cramps by lowering prostaglandins.', 'fact', 'Remember the squeeze chemicals?', 'Correct! These anti-inflammatories reduce the chemicals that make the womb contract.', 'They work best taken at the first sign of pain.', 'ACOG: Dysmenorrhea', 'draft', true, now()),
  ('period-care-4-08', 'period-care', 4, 'Paracetamol and ibuprofen work in exactly the same way.', 'myth', 'Same box, same job?', 'Not true! Ibuprofen is an anti-inflammatory that lowers prostaglandins. Paracetamol works differently and isn’t anti-inflammatory.', 'Always check doses and ask a pharmacist if unsure.', 'NHS: Ibuprofen', 'draft', true, now()),
  ('period-care-4-09', 'period-care', 4, 'Tranexamic acid is a non-hormonal medicine that can make heavy periods lighter.', 'fact', 'No hormones needed.', 'Correct! It helps blood clot in the womb, so less blood is lost. It’s only taken during your period.', 'It doesn’t help with pain, though.', 'NHS: Tranexamic acid', 'draft', true, now()),
  ('period-care-4-10', 'period-care', 4, 'A hormonal coil (IUS) is one treatment that can make heavy periods much lighter.', 'fact', 'Thin lining, light period.', 'Correct! It releases a small amount of progestogen that keeps the womb lining thin.', 'Some people’s periods stop completely with it.', 'NHS: Heavy periods', 'draft', true, now()),
  ('period-care-5-01', 'period-care', 5, 'Tampons contain asbestos to make you bleed more.', 'myth', 'Classic internet rumour.', 'Not true! This myth has been around for years and has no basis. Tampons are regulated medical products.', 'In the US, the FDA regulates tampons as medical devices.', 'FDA: The facts on tampons', 'draft', true, now()),
  ('period-care-5-02', 'period-care', 5, 'Using the lowest-absorbency tampon you need lowers the risk of TSS.', 'fact', 'Less is more.', 'Correct! Higher absorbency is linked with higher TSS risk, so match the tampon to your flow.', 'Change at least every 4 to 8 hours.', 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('period-care-5-03', 'period-care', 5, 'Heavy periods are one of the most common causes of iron deficiency anaemia in young women.', 'fact', 'Where does iron go?', 'Correct! Losing more blood each month means losing more iron.', 'Signs include tiredness, breathlessness and pale skin.', 'NHS: Iron deficiency anaemia', 'draft', true, now()),
  ('period-care-5-04', 'period-care', 5, 'A ferritin blood test measures how much oxygen your blood carries.', 'myth', 'Ferr- means iron.', 'Not true! Ferritin shows how much iron your body has stored.', 'Low ferritin can show up before anaemia does.', 'NHS: Ferritin test', 'draft', true, now()),
  ('period-care-5-05', 'period-care', 5, 'You can have low iron stores even if your haemoglobin is normal.', 'fact', 'Two different tests.', 'Correct! Your iron stores can run low before your haemoglobin drops.', 'This is called iron deficiency without anaemia.', 'NIH Office of Dietary Supplements: Iron', 'draft', true, now()),
  ('period-care-5-06', 'period-care', 5, 'Bleeding disorders like von Willebrand disease are extremely rare in people with heavy periods.', 'myth', 'Doctors check for a reason.', 'Not true! A bleeding disorder is found in a fair number of people with heavy periods, so doctors may test for one.', 'Easy bruising and nosebleeds can be other clues.', 'ACOG: Von Willebrand disease', 'draft', true, now()),
  ('period-care-5-07', 'period-care', 5, 'Soaking through a pad or tampon every hour for several hours in a row needs urgent medical advice.', 'fact', 'How fast is too fast?', 'Correct! Very heavy bleeding like this, especially with dizziness, should be checked urgently.', 'Keep track of how often you change.', 'ACOG: Heavy menstrual bleeding', 'draft', true, now()),
  ('period-care-5-08', 'period-care', 5, 'Mefenamic acid, used for period pain, is a type of antibiotic.', 'myth', 'Same family as ibuprofen.', 'Not true! Mefenamic acid is an anti-inflammatory painkiller, like ibuprofen.', 'It can also make periods a bit lighter.', 'NHS: Mefenamic acid', 'draft', true, now()),
  ('period-care-5-09', 'period-care', 5, 'Menstrual discs sit higher up in the vagina than cups do.', 'fact', 'Disc vs cup.', 'Correct! Discs tuck up behind the pubic bone in the widest part of the vagina, while cups sit lower.', 'Discs are flatter and more flexible than cups.', 'Cleveland Clinic: Menstrual discs', 'draft', true, now()),
  ('period-care-5-10', 'period-care', 5, 'Reusable pads should be soaked in bleach after every use.', 'myth', 'Gentle care.', 'Not true! Rinse in cold water, then wash as directed. Bleach can damage the fabric and irritate skin.', 'Drying them in sunlight can help lift stains.', 'Which?: Reusable pads care', 'draft', true, now()),
  ('hormones-101-4-01', 'hormones-101', 4, 'The hypothalamus, pituitary and ovaries work together in a loop called the HPO axis.', 'fact', 'Three letters, one team.', 'Correct! The hypothalamus signals the pituitary, the pituitary signals the ovaries, and the ovaries signal back.', 'It’s like a group chat for your cycle.', 'Endocrine Society: Menstrual cycle', 'draft', true, now()),
  ('hormones-101-4-02', 'hormones-101', 4, 'High oestrogen always tells the brain to make less LH.', 'myth', 'Is there a twist mid-cycle?', 'Not always! Usually oestrogen slows things down, but when it stays high just before ovulation it flips to ‘go’ and triggers the LH surge.', 'This flip is called positive feedback.', 'Endocrine Society: Menstrual cycle', 'draft', true, now()),
  ('hormones-101-4-03', 'hormones-101', 4, 'Oestradiol is the main form of oestrogen before menopause.', 'fact', 'Oestrogen has a family.', 'Correct! There are several forms, and oestradiol is the strongest and most common in the reproductive years.', 'After menopause, a form called oestrone becomes the main one.', 'Cleveland Clinic: Estrogen', 'draft', true, now()),
  ('hormones-101-4-04', 'hormones-101', 4, 'Progesterone is mostly made by the brain.', 'myth', 'Remember the yellow body?', 'Not true! In the cycle, it’s mostly made by the corpus luteum in the ovary.', 'In pregnancy, the placenta takes over.', 'Cleveland Clinic: Progesterone', 'draft', true, now()),
  ('hormones-101-4-05', 'hormones-101', 4, 'Anti-Müllerian hormone (AMH) is made by small follicles in the ovaries.', 'fact', 'A follicle headcount.', 'Correct! AMH gives a rough idea of how many follicles are developing.', 'It doesn’t predict when someone can get pregnant.', 'Cleveland Clinic: AMH', 'draft', true, now()),
  ('hormones-101-4-06', 'hormones-101', 4, 'Women have about the same testosterone levels as men.', 'myth', 'How big is the gap?', 'Not true! Women usually have around a tenth to a twentieth of the testosterone men have.', 'It still matters for energy, mood and libido.', 'Cleveland Clinic: Testosterone', 'draft', true, now()),
  ('hormones-101-4-07', 'hormones-101', 4, 'High prolactin, the hormone that makes breast milk, can stop periods.', 'fact', 'Nature’s pause button.', 'Correct! High prolactin can block ovulation. That’s partly why breastfeeding can delay periods.', 'Some medicines can raise prolactin too.', 'NHS: Prolactinoma', 'draft', true, now()),
  ('hormones-101-4-08', 'hormones-101', 4, 'Thyroid problems can only make periods lighter, never heavier.', 'myth', 'Two directions.', 'Not true! An underactive thyroid can cause heavy periods, and an overactive one can make them lighter or less frequent.', 'Thyroid checks are a common test for period problems.', 'NHS: Underactive thyroid', 'draft', true, now()),
  ('hormones-101-4-09', 'hormones-101', 4, 'Cortisol, the stress hormone, can interfere with the brain signals that run your cycle.', 'fact', 'Stress travels.', 'Correct! High stress can disrupt GnRH pulses, delaying ovulation and periods.', 'That’s why a stressful month can mean a late period.', 'Endocrine Society: Stress', 'draft', true, now()),
  ('hormones-101-4-10', 'hormones-101', 4, 'Insulin can push the ovaries to make more androgens.', 'fact', 'Sugar hormone, hair hormone?', 'Correct! High insulin levels can increase androgen production, which is part of how PCOS works.', 'That’s why some PCOS treatments target insulin.', 'NHS: PCOS', 'draft', true, now()),
  ('hormones-101-5-01', 'hormones-101', 5, 'FSH and LH are made in the ovaries.', 'myth', 'Follow the chain upwards.', 'Not true! FSH and LH are made by the pituitary gland in your brain. They act on the ovaries.', 'Their full names are follicle-stimulating and luteinising hormone.', 'Endocrine Society: Menstrual cycle', 'draft', true, now()),
  ('hormones-101-5-02', 'hormones-101', 5, 'Some endometriosis medicines switch off the ovaries for a while by acting on GnRH signals.', 'fact', 'Turn the system off.', 'Correct! GnRH-based medicines can calm the HPO axis, lowering oestrogen and easing symptoms.', 'They’re usually used for a limited time.', 'NHS: Endometriosis treatment', 'draft', true, now()),
  ('hormones-101-5-03', 'hormones-101', 5, 'Inhibin is a hormone that boosts FSH.', 'myth', 'The name is a clue.', 'Not true! Inhibin, made by the ovaries, inhibits FSH, as its name suggests.', 'It helps stop too many follicles growing at once.', 'Endocrine Society: Menstrual cycle', 'draft', true, now()),
  ('hormones-101-5-04', 'hormones-101', 5, 'SHBG carries sex hormones in the blood, and only the ‘free’ part is active.', 'fact', 'Some hormones are passengers.', 'Correct! Sex hormone-binding globulin holds onto hormones, so only the unbound part can act.', 'Low SHBG means more free testosterone.', 'Cleveland Clinic: SHBG', 'draft', true, now()),
  ('hormones-101-5-05', 'hormones-101', 5, 'Oestrogen and progesterone are made from protein.', 'myth', 'Steroid hormones.', 'Not true! They’re steroid hormones made from cholesterol.', 'Your body makes most of its own cholesterol.', 'Cleveland Clinic: Steroid hormones', 'draft', true, now()),
  ('hormones-101-5-06', 'hormones-101', 5, 'Fat tissue can turn androgens into oestrogen using an enzyme called aromatase.', 'fact', 'Fat is active.', 'Correct! This is how most oestrogen is made after menopause.', 'Some breast cancer medicines block aromatase.', 'Cleveland Clinic: Estrogen', 'draft', true, now()),
  ('hormones-101-5-07', 'hormones-101', 5, 'The combined pill works mainly by destroying eggs.', 'myth', 'What does the pill stop?', 'Not true! It works mainly by stopping ovulation, so no egg is released. It doesn’t destroy eggs.', 'The monthly ‘bleed’ on the pill isn’t a true period.', 'NHS: Combined pill', 'draft', true, now()),
  ('hormones-101-5-08', 'hormones-101', 5, 'The pituitary makes both prolactin and TSH, the hormone that tells your thyroid to work.', 'fact', 'Master gland, many jobs.', 'Correct! The pituitary controls many glands, including the thyroid and breasts.', 'It also makes growth hormone.', 'NHS: Pituitary gland', 'draft', true, now()),
  ('hormones-101-5-09', 'hormones-101', 5, 'Kisspeptin is a protein in saliva with nothing to do with hormones.', 'myth', 'Sweet name, big job.', 'Not true! Kisspeptin is made in the brain and helps switch on GnRH, so it’s key to starting puberty.', 'It was named after Hershey’s Kisses, made in the town where it was discovered.', 'Endocrine Society: Puberty', 'draft', true, now()),
  ('hormones-101-5-10', 'hormones-101', 5, 'A ‘normal’ hormone result can depend on which day of the cycle the blood test was taken.', 'fact', 'Timing matters.', 'Correct! Hormones swing so much that doctors often ask for tests on specific cycle days.', 'Progesterone is often checked about a week before a period.', 'NHS: Hormone tests', 'draft', true, now()),
  ('skin-hormones-4-01', 'skin-hormones', 4, 'Acne starts when oil and dead skin cells block hair follicles.', 'fact', 'What clogs a pore?', 'Correct! Sebum and dead skin cells form a plug, and that’s where spots begin.', 'Each pore is actually the opening of a hair follicle.', 'American Academy of Dermatology: Acne', 'draft', true, now()),
  ('skin-hormones-4-02', 'skin-hormones', 4, 'Blackheads are dirt trapped in your pores.', 'myth', 'Why are they dark?', 'Not true! The dark colour comes from oil and skin cells reacting with air, not dirt. Scrubbing won’t fix them.', 'Whiteheads are the same plug with skin over the top.', 'American Academy of Dermatology: Acne', 'draft', true, now()),
  ('skin-hormones-4-03', 'skin-hormones', 4, 'A bacterium called Cutibacterium acnes plays a part in red, inflamed spots.', 'fact', 'A skin resident.', 'Correct! It lives on everyone’s skin, but in blocked pores it can trigger inflammation.', 'It used to be called Propionibacterium acnes.', 'American Academy of Dermatology: Acne', 'draft', true, now()),
  ('skin-hormones-4-04', 'skin-hormones', 4, 'Retinoids work by drying spots out with alcohol.', 'myth', 'Think skin cell turnover.', 'Not true! Retinoids speed up skin cell turnover, which stops pores clogging.', 'Results usually take 8 to 12 weeks.', 'American Academy of Dermatology: Retinoids', 'draft', true, now()),
  ('skin-hormones-4-05', 'skin-hormones', 4, 'Retinoids can make your skin more sensitive to the sun.', 'fact', 'Fresh skin, fragile skin.', 'Correct! Use sun cream daily when using a retinoid.', 'Many people use retinoids at night for this reason.', 'American Academy of Dermatology: Retinoids', 'draft', true, now()),
  ('skin-hormones-4-06', 'skin-hormones', 4, 'Benzoyl peroxide works by switching off your hormones.', 'myth', 'What does it actually target?', 'Not true! It kills acne bacteria and helps unclog pores. It doesn’t touch your hormones.', 'Bacteria don’t become resistant to it, unlike antibiotics.', 'American Academy of Dermatology: Benzoyl peroxide', 'draft', true, now()),
  ('skin-hormones-4-07', 'skin-hormones', 4, 'Salicylic acid helps unclog pores by loosening dead skin cells.', 'fact', 'BHA.', 'Correct! It’s a beta hydroxy acid that can get into oily pores.', 'It comes from the same family as aspirin.', 'American Academy of Dermatology: Acne', 'draft', true, now()),
  ('skin-hormones-4-08', 'skin-hormones', 4, 'Acne scars and dark marks left after spots are the same thing.', 'myth', 'Texture vs colour.', 'Not true! Dark marks are colour changes that usually fade. Scars change the skin’s texture and are more lasting.', 'Sun cream helps dark marks fade faster.', 'American Academy of Dermatology: Acne scars', 'draft', true, now()),
  ('skin-hormones-4-09', 'skin-hormones', 4, 'Darker skin tones are more likely to get dark marks after spots.', 'fact', 'Melanin reacts.', 'Correct! This is called post-inflammatory hyperpigmentation, and it’s common in brown and Black skin.', 'Treating spots early helps prevent marks.', 'American Academy of Dermatology: Dark spots', 'draft', true, now()),
  ('skin-hormones-4-10', 'skin-hormones', 4, 'Hormonal acne mostly shows up on the forehead.', 'myth', 'Lower down?', 'Not quite! Hormone-linked acne often shows up on the jawline, chin and lower face.', 'It can flare before a period.', 'American Academy of Dermatology: Acne', 'draft', true, now()),
  ('skin-hormones-5-01', 'skin-hormones', 5, 'Isotretinoin, a strong acne medicine, must never be taken during pregnancy because it can harm a baby.', 'fact', 'Strict rules.', 'Correct! That’s why people who could get pregnant need a pregnancy prevention plan while taking it.', 'It’s only prescribed by specialists in the UK.', 'NHS: Isotretinoin', 'draft', true, now()),
  ('skin-hormones-5-02', 'skin-hormones', 5, 'Spironolactone is an antibiotic used for acne.', 'myth', 'Think anti-androgen.', 'Not true! It blocks the effect of androgens on the skin. It’s not an antibiotic.', 'It was first made as a blood pressure medicine.', 'American Academy of Dermatology: Acne', 'draft', true, now()),
  ('skin-hormones-5-03', 'skin-hormones', 5, 'Acne antibiotics are often combined with benzoyl peroxide to help stop bacteria becoming resistant.', 'fact', 'Teamwork.', 'Correct! Using them together lowers the chance of antibiotic resistance.', 'Antibiotics for acne are usually limited to a few months.', 'American Academy of Dermatology: Acne', 'draft', true, now()),
  ('skin-hormones-5-04', 'skin-hormones', 5, 'Azelaic acid can help with both acne and dark marks.', 'fact', 'Two jobs.', 'Correct! It calms spots and can fade post-acne dark marks.', 'It’s often safe to use in pregnancy.', 'American Academy of Dermatology: Acne', 'draft', true, now()),
  ('skin-hormones-5-05', 'skin-hormones', 5, 'Oil production in the skin is controlled mainly by oestrogen.', 'myth', 'Which hormone turns oil up?', 'Not true! Androgens drive oil production. Oestrogen tends to turn it down.', 'That’s why acne often flares when androgen effects are higher.', 'American Academy of Dermatology: Acne', 'draft', true, now()),
  ('skin-hormones-5-06', 'skin-hormones', 5, 'Oestrogen tends to reduce oil production, which is one reason some pills help acne.', 'fact', 'The flip side.', 'Correct! Combined pills can lower androgen effects and oil, which can improve acne.', 'Not all pills help acne.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-5-07', 'skin-hormones', 5, 'Acne in women over 25 is rare.', 'myth', 'Is acne just for teens?', 'Not true! Adult acne is common in women, often around the jaw and chin.', 'Many women first get acne as adults.', 'American Academy of Dermatology: Acne', 'draft', true, now()),
  ('skin-hormones-5-08', 'skin-hormones', 5, 'Hidradenitis suppurativa causes painful lumps in places like the armpits and groin, and it’s not caused by poor hygiene.', 'fact', 'Not about washing.', 'Correct! It’s a long-term inflammatory skin condition, and good treatments exist.', 'It often starts after puberty.', 'NHS: Hidradenitis suppurativa', 'draft', true, now()),
  ('skin-hormones-5-09', 'skin-hormones', 5, 'Rosacea and acne are the same condition.', 'myth', 'Similar look, different cause.', 'Not true! Rosacea causes flushing, redness and sometimes bumps, usually in adults. It needs different treatment.', 'Rosacea usually has no blackheads.', 'NHS: Rosacea', 'draft', true, now()),
  ('skin-hormones-5-10', 'skin-hormones', 5, 'SPF 50 lets you stay in the sun twice as long as SPF 25 without reapplying.', 'myth', 'How long does sun cream last?', 'Not true! Whatever the SPF, reapply at least every 2 hours and after swimming or sweating.', 'Most people put on less than half the amount needed.', 'NHS: Sunscreen and sun safety', 'draft', true, now()),
  ('pcos-4-01', 'pcos', 4, 'To diagnose PCOS in adults, doctors usually look for 2 out of 3 things: irregular ovulation, signs of high androgens, and polycystic ovaries.', 'fact', 'Two out of three.', 'Correct! These are called the Rotterdam criteria, and other causes are ruled out first.', 'You don’t need a scan if the first two are present.', 'International PCOS Guideline (2023)', 'draft', true, now()),
  ('pcos-4-02', 'pcos', 4, 'Teenagers are diagnosed with PCOS using an ovary scan.', 'myth', 'Teen ovaries look different.', 'Not true! Ultrasound isn’t recommended for diagnosis within 8 years of a first period, because many healthy teen ovaries look ‘polycystic’.', 'Teens are diagnosed using cycles and androgen signs.', 'International PCOS Guideline (2023)', 'draft', true, now()),
  ('pcos-4-03', 'pcos', 4, 'PCOS is linked to a higher chance of sleep apnoea.', 'fact', 'Sleep matters too.', 'Correct! Sleep apnoea is more common in PCOS, so snoring and daytime tiredness are worth mentioning.', 'Treating it can help energy and mood.', 'International PCOS Guideline (2023)', 'draft', true, now()),
  ('pcos-4-04', 'pcos', 4, 'PCOS goes away completely after menopause.', 'myth', 'What about the metabolic side?', 'Not quite! Periods stop, but risks like type 2 diabetes and heart health still need looking after.', 'Regular check-ups remain useful.', 'International PCOS Guideline (2023)', 'draft', true, now()),
  ('pcos-4-05', 'pcos', 4, 'Metformin, a diabetes medicine, is sometimes used to treat PCOS.', 'fact', 'Insulin helper.', 'Correct! It helps the body use insulin better, which can help some people’s symptoms.', 'It can upset the stomach at first.', 'NHS: PCOS treatment', 'draft', true, now()),
  ('pcos-4-06', 'pcos', 4, 'In PCOS, insulin resistance only happens in people with a higher weight.', 'myth', 'Size isn’t the whole story.', 'Not true! People with PCOS of any weight can have insulin resistance.', 'It’s thought to be part of PCOS itself.', 'International PCOS Guideline (2023)', 'draft', true, now()),
  ('pcos-4-07', 'pcos', 4, 'Long gaps between periods can let the womb lining build up, so doctors may bring on a regular bleed.', 'fact', 'Lining buildup.', 'Correct! Regular bleeds, often with hormone treatment, protect the womb lining.', 'Three or more bleeds a year is a common aim.', 'NHS: PCOS', 'draft', true, now()),
  ('pcos-4-08', 'pcos', 4, 'PCOS is caused by eating too much sugar.', 'myth', 'Genes or sugar?', 'Not true! PCOS is linked to genes and hormones. Diet can help manage it, but sugar doesn’t cause it.', 'It often runs in families.', 'NHS: PCOS', 'draft', true, now()),
  ('pcos-4-09', 'pcos', 4, 'AMH levels are often higher in people with PCOS.', 'fact', 'More follicles, more AMH.', 'Correct! Many small follicles mean more AMH.', 'AMH is made by small growing follicles.', 'International PCOS Guideline (2023)', 'draft', true, now()),
  ('pcos-4-10', 'pcos', 4, 'Extra hair growth in PCOS is caused by too much oestrogen.', 'myth', 'Which hormone grows hair?', 'Not true! It’s caused by higher androgens like testosterone.', 'Doctors call it hirsutism.', 'NHS: PCOS', 'draft', true, now()),
  ('pcos-5-01', 'pcos', 5, 'The 2023 international PCOS guideline allows an AMH blood test instead of an ultrasound for adults.', 'fact', 'A newer option.', 'Correct! AMH can now stand in for the ovary part of the criteria in adults.', 'It’s not recommended for teens.', 'International PCOS Guideline (2023)', 'draft', true, now()),
  ('pcos-5-02', 'pcos', 5, 'Polycystic-looking ovaries on a scan mean you definitely have PCOS.', 'myth', 'Common in people without PCOS.', 'Not true! Lots of people without PCOS have ovaries that look polycystic. A scan alone isn’t a diagnosis.', 'That’s why the 2-out-of-3 rule exists.', 'International PCOS Guideline (2023)', 'draft', true, now()),
  ('pcos-5-03', 'pcos', 5, 'In PCOS, high insulin can lower SHBG, leaving more free testosterone in the blood.', 'fact', 'Remember the hormone taxi?', 'Correct! Less SHBG means more active testosterone, which can worsen acne and hair growth.', 'This is one link between insulin and androgens.', 'International PCOS Guideline (2023)', 'draft', true, now()),
  ('pcos-5-04', 'pcos', 5, 'Inositol is a proven cure for PCOS.', 'myth', 'Proven or popular?', 'Not true! Inositol is popular, but the guideline says the evidence is limited. Talk to a doctor before trying it.', 'There is no cure for PCOS yet.', 'International PCOS Guideline (2023)', 'draft', true, now()),
  ('pcos-5-05', 'pcos', 5, 'People with PCOS have a higher chance of gestational diabetes in pregnancy.', 'fact', 'Insulin again.', 'Correct! That’s why pregnant people with PCOS may get early screening.', 'Healthy habits before pregnancy help.', 'International PCOS Guideline (2023)', 'draft', true, now()),
  ('pcos-5-06', 'pcos', 5, 'PCOS was first described in the 2000s.', 'myth', 'Older than you think.', 'Not true! Stein and Leventhal described it in 1935.', 'It was once called Stein-Leventhal syndrome.', 'Stein and Leventhal, American Journal of Obstetrics and Gynecology (1935)', 'draft', true, now()),
  ('pcos-5-07', 'pcos', 5, 'Up to about 70% of people with PCOS may not be diagnosed.', 'fact', 'Hidden numbers.', 'Correct! Many people don’t know they have it, especially if symptoms are mild.', 'Tracking cycles can help spot it.', 'International PCOS Guideline (2023)', 'draft', true, now()),
  ('pcos-5-08', 'pcos', 5, 'Metformin works mainly by lowering testosterone directly.', 'myth', 'What does it target?', 'Not true! It mainly helps the body respond to insulin. Any drop in androgens is a knock-on effect.', 'It’s one of the most used medicines worldwide.', 'NHS: Metformin', 'draft', true, now()),
  ('pcos-5-09', 'pcos', 5, 'Having fewer than about 8 periods a year can be a sign of irregular ovulation.', 'fact', 'Counting periods.', 'Correct! Cycles longer than 35 days or fewer than 8 periods a year suggest irregular ovulation in adults.', 'For teens, the rules are a bit different.', 'International PCOS Guideline (2023)', 'draft', true, now()),
  ('pcos-5-10', 'pcos', 5, 'Losing weight is the only treatment that works for PCOS.', 'myth', 'Many tools.', 'Not true! Medicines, hormone treatments, skin and hair treatments, and mental health support all help.', 'Treatment is tailored to each person’s symptoms.', 'International PCOS Guideline (2023)', 'draft', true, now()),
  ('food-cycle-4-01', 'food-cycle', 4, 'Girls aged 11 to 18 in the UK are advised to get 14.8 mg of iron a day.', 'fact', 'A number to remember.', 'Correct! That’s much more than younger children need, because periods mean losing iron.', 'Boys of the same age need 11.3 mg.', 'NHS: Iron', 'draft', true, now()),
  ('food-cycle-4-02', 'food-cycle', 4, 'Haem iron comes from plants.', 'myth', 'Haem, like haemoglobin.', 'Not true! Haem iron comes from meat and fish. Plant iron is called non-haem iron.', 'Haem iron is absorbed more easily.', 'NIH Office of Dietary Supplements: Iron', 'draft', true, now()),
  ('food-cycle-4-03', 'food-cycle', 4, 'Calcium taken with an iron-rich meal can reduce how much iron you absorb.', 'fact', 'Minerals compete.', 'Correct! Calcium can block iron absorption, so space supplements apart if you take both.', 'Food sources together are less of a concern.', 'NIH Office of Dietary Supplements: Iron', 'draft', true, now()),
  ('food-cycle-4-04', 'food-cycle', 4, 'Vitamin D is mostly found in fruit.', 'myth', 'Where does vitamin D come from?', 'Not true! Most vitamin D comes from sunlight on skin, plus oily fish, eggs and fortified foods.', 'It’s sometimes called the sunshine vitamin.', 'NHS: Vitamin D', 'draft', true, now()),
  ('food-cycle-4-05', 'food-cycle', 4, 'In the UK, everyone is advised to consider a vitamin D supplement in autumn and winter.', 'fact', 'Less sun, less D.', 'Correct! There isn’t enough sunlight in UK winters to make enough vitamin D.', 'People with darker skin may need it all year.', 'NHS: Vitamin D', 'draft', true, now()),
  ('food-cycle-4-06', 'food-cycle', 4, 'Folate is found in leafy greens, beans and fortified cereals.', 'fact', 'B9.', 'Correct! Folate helps make healthy red blood cells.', 'Folic acid is the man-made form.', 'NHS: B vitamins and folic acid', 'draft', true, now()),
  ('food-cycle-4-07', 'food-cycle', 4, 'Omega-3 fats are only found in fish.', 'myth', 'Seeds?', 'Not true! Flaxseed, chia seeds and walnuts have a plant form of omega-3.', 'The body converts only a small amount of it.', 'NHS: Fish and shellfish', 'draft', true, now()),
  ('food-cycle-4-08', 'food-cycle', 4, 'Iron needs go up once periods start.', 'fact', 'Why?', 'Correct! Periods mean losing blood, and blood holds iron.', 'Younger girls need about 8.7 mg a day.', 'NHS: Iron', 'draft', true, now()),
  ('food-cycle-4-09', 'food-cycle', 4, 'Taking more vitamins than you need is always harmless.', 'myth', 'Too much of a good thing?', 'Not true! Some vitamins and minerals, like vitamin A and iron, can be harmful in high doses.', 'Stick to recommended amounts.', 'NHS: Vitamins and minerals', 'draft', true, now()),
  ('food-cycle-4-10', 'food-cycle', 4, 'Sugar cravings before your period prove your blood sugar is low.', 'myth', 'Proof?', 'Not true! Cravings are common in PMS, but they don’t prove low blood sugar.', 'Hormone shifts can change appetite.', 'ACOG: Premenstrual syndrome', 'draft', true, now()),
  ('food-cycle-5-01', 'food-cycle', 5, 'Phytates in wholegrains and beans can reduce iron absorption, and soaking or sprouting can help.', 'fact', 'Kitchen tricks.', 'Correct! Soaking and sprouting lower phytates, so more iron gets absorbed.', 'Fermenting foods also helps.', 'NIH Office of Dietary Supplements: Iron', 'draft', true, now()),
  ('food-cycle-5-02', 'food-cycle', 5, 'Ferritin goes up when your iron stores are low.', 'myth', 'Stores and readings.', 'Not true! Low ferritin means low iron stores.', 'It’s often the first test to drop.', 'NHS: Ferritin test', 'draft', true, now()),
  ('food-cycle-5-03', 'food-cycle', 5, 'An infection or inflammation can make ferritin look higher than your true iron stores.', 'fact', 'Misleading results.', 'Correct! Ferritin rises with inflammation, so doctors look at other results too.', 'Doctors call this an acute-phase reactant.', 'NIH Office of Dietary Supplements: Iron', 'draft', true, now()),
  ('food-cycle-5-04', 'food-cycle', 5, 'Vitamin B12 is found naturally in most plant foods.', 'myth', 'Where does B12 come from?', 'Not true! B12 is naturally found in animal foods. Vegans need fortified foods or supplements.', 'B12 is made by bacteria.', 'NHS: Vitamin B12', 'draft', true, now()),
  ('food-cycle-5-05', 'food-cycle', 5, 'Eating too little for how much you train can lower oestrogen and weaken bones.', 'fact', 'Energy budget.', 'Correct! Low energy availability can stop periods and reduce bone strength.', 'It’s part of RED-S.', 'NHS: Stopped or missed periods', 'draft', true, now()),
  ('food-cycle-5-06', 'food-cycle', 5, 'The calcium in spinach is absorbed as easily as the calcium in milk.', 'myth', 'Spinach has a catch.', 'Not true! Spinach contains oxalates that bind calcium, so very little is absorbed.', 'Kale and broccoli are better plant sources.', 'NIH Office of Dietary Supplements: Calcium', 'draft', true, now()),
  ('food-cycle-5-07', 'food-cycle', 5, 'Iron taken every other day can be absorbed as well as, or better than, daily doses.', 'fact', 'Hepcidin is involved.', 'Correct! A daily dose raises hepcidin, which blocks absorption the next day. Always follow your doctor’s advice.', 'Some doctors now prescribe alternate-day iron.', 'Stoffel et al., Lancet Haematology (2017)', 'draft', true, now()),
  ('food-cycle-5-08', 'food-cycle', 5, 'Hepcidin is a hormone that helps you absorb more iron.', 'myth', 'Gatekeeper.', 'Not true! Hepcidin blocks iron absorption when stores are full or there’s inflammation.', 'It’s made in the liver.', 'NIH Office of Dietary Supplements: Iron', 'draft', true, now()),
  ('food-cycle-5-09', 'food-cycle', 5, 'Calcium may help ease some PMS symptoms.', 'fact', 'Bones and moods?', 'Correct! Some research suggests calcium can help PMS symptoms.', 'Food sources are a good place to start.', 'ACOG: Premenstrual syndrome', 'draft', true, now()),
  ('food-cycle-5-10', 'food-cycle', 5, 'Craving ice is never linked to low iron.', 'myth', 'Strange cravings.', 'Not true! Craving ice, called pagophagia, can be a sign of iron deficiency.', 'It often stops once iron levels are treated.', 'NHS: Iron deficiency anaemia', 'draft', true, now()),
  ('mood-hormones-4-01', 'mood-hormones', 4, 'Allopregnanolone, made from progesterone, acts on the same brain receptors as some calming medicines.', 'fact', 'GABA.', 'Correct! It acts on GABA receptors, which helps explain mood changes for some people.', 'These receptors are the brain’s calm-down system.', 'NIH: PMDD sensitivity study (2017)', 'draft', true, now()),
  ('mood-hormones-4-02', 'mood-hormones', 4, 'PMDD is caused by having abnormal hormone levels.', 'myth', 'Levels or sensitivity?', 'Not true! People with PMDD usually have normal hormone levels. Their brains react more strongly to normal changes.', 'This was shown in research at the NIH.', 'NIH: PMDD sensitivity study (2017)', 'draft', true, now()),
  ('mood-hormones-4-03', 'mood-hormones', 4, 'To diagnose PMDD, doctors usually ask for daily symptom tracking over at least two cycles.', 'fact', 'Data over time.', 'Correct! Tracking shows if symptoms follow the cycle.', 'Spot it logs can help.', 'ACOG: Premenstrual syndrome', 'draft', true, now()),
  ('mood-hormones-4-04', 'mood-hormones', 4, 'Antidepressants for PMDD only work after months of use.', 'myth', 'Speed?', 'Not true! For PMDD, SSRIs often work within days, so some people take them only before their period.', 'This is different from depression.', 'ACOG: Premenstrual syndrome', 'draft', true, now()),
  ('mood-hormones-4-05', 'mood-hormones', 4, 'Some people take SSRIs only in the second half of their cycle to treat PMDD.', 'fact', 'Timed treatment.', 'Correct! This is called luteal-phase dosing.', 'A doctor can help decide what’s best.', 'ACOG: Premenstrual syndrome', 'draft', true, now()),
  ('mood-hormones-4-06', 'mood-hormones', 4, 'PMS and PMDD symptoms last all month long.', 'myth', 'Timing is the clue.', 'Not true! They happen in the luteal phase and ease within a few days of the period starting.', 'Symptoms all month point to something else.', 'ACOG: Premenstrual syndrome', 'draft', true, now()),
  ('mood-hormones-4-07', 'mood-hormones', 4, 'Oestrogen can boost serotonin activity in the brain.', 'fact', 'Feel-good link.', 'Correct! This is one reason falling oestrogen can affect mood.', 'Serotonin also affects sleep and appetite.', 'Cleveland Clinic: Estrogen', 'draft', true, now()),
  ('mood-hormones-4-08', 'mood-hormones', 4, 'Only a tiny number of people get mood changes before a period.', 'myth', 'How many?', 'Not true! As many as 3 in 4 people with periods notice some PMS symptoms.', 'Most cases are mild.', 'ACOG: Premenstrual syndrome', 'draft', true, now()),
  ('mood-hormones-4-09', 'mood-hormones', 4, 'Premenstrual exacerbation is when an existing condition, like depression, gets worse before a period.', 'fact', 'PME.', 'Correct! It’s different from PMDD, and tracking helps tell them apart.', 'Asthma and migraines can also worsen.', 'IAPMD: PME', 'draft', true, now()),
  ('mood-hormones-4-10', 'mood-hormones', 4, 'Cortisol only rises when something bad happens.', 'myth', 'Morning hormone.', 'Not true! Cortisol follows a daily rhythm and peaks in the morning to help you wake up.', 'It’s called the cortisol awakening response.', 'Cleveland Clinic: Cortisol', 'draft', true, now()),
  ('mood-hormones-5-01', 'mood-hormones', 5, 'Around 3 to 8% of people who have periods are thought to have PMDD.', 'fact', 'Rarer than PMS.', 'Correct! PMDD is much less common than PMS, but it can be severe.', 'It’s often missed.', 'ACOG: Premenstrual syndrome', 'draft', true, now()),
  ('mood-hormones-5-02', 'mood-hormones', 5, 'PMDD is not recognised as its own diagnosis.', 'myth', 'Check the manuals.', 'Not true! PMDD is listed as a depressive disorder in the DSM-5 and in the WHO’s ICD-11.', 'It was added to DSM-5 in 2013.', 'American Psychiatric Association: DSM-5', 'draft', true, now()),
  ('mood-hormones-5-03', 'mood-hormones', 5, 'PMDD symptoms usually ease within a few days after a period starts.', 'fact', 'Relief arrives.', 'Correct! The timing is a key feature.', 'This pattern repeats each cycle.', 'ACOG: Premenstrual syndrome', 'draft', true, now()),
  ('mood-hormones-5-04', 'mood-hormones', 5, 'Dopamine is the brain’s sleep hormone.', 'myth', 'Wrong chemical.', 'Not true! Melatonin is the sleep hormone. Dopamine is linked to reward and motivation.', 'Dopamine is a neurotransmitter.', 'Cleveland Clinic: Dopamine', 'draft', true, now()),
  ('mood-hormones-5-05', 'mood-hormones', 5, 'Most of the body’s serotonin is made in the gut.', 'fact', 'Gut feelings.', 'Correct! About 90% is made in the gut, though brain serotonin is made separately.', 'The gut has its own nervous system.', 'Cleveland Clinic: Serotonin', 'draft', true, now()),
  ('mood-hormones-5-06', 'mood-hormones', 5, 'Seasonal low mood (SAD) has nothing to do with daylight.', 'myth', 'Winter blues.', 'Not true! SAD is linked to less daylight in autumn and winter.', 'Light therapy can help some people.', 'NHS: Seasonal affective disorder', 'draft', true, now()),
  ('mood-hormones-5-07', 'mood-hormones', 5, 'CBT, a talking therapy, can help some people with PMDD.', 'fact', 'Tools for the mind.', 'Correct! CBT can help people manage symptoms.', 'It’s often combined with other treatments.', 'ACOG: Premenstrual syndrome', 'draft', true, now()),
  ('mood-hormones-5-08', 'mood-hormones', 5, 'Hormonal contraception always makes mood worse.', 'myth', 'Always?', 'Not true! Effects vary from person to person. Some feel better, some worse, and many notice no change.', 'Talk to a doctor if your mood changes.', 'NHS: Combined pill', 'draft', true, now()),
  ('mood-hormones-5-09', 'mood-hormones', 5, 'Some combined pills are taken without a break to help PMDD symptoms.', 'fact', 'Skipping the gap.', 'Correct! Continuous use can reduce hormone swings.', 'This is done with a doctor’s advice.', 'ACOG: Premenstrual syndrome', 'draft', true, now()),
  ('mood-hormones-5-10', 'mood-hormones', 5, 'Feeling better after exercise is all in your head, with no real change in the body.', 'myth', 'Endorphins.', 'Not true! Exercise releases endorphins and other brain chemicals that lift mood.', 'Even short sessions help.', 'NHS Every Mind Matters', 'draft', true, now()),
  ('sleep-cycle-4-01', 'sleep-cycle', 4, 'Your core body temperature drops in the evening to help you fall asleep.', 'fact', 'Cool down.', 'Correct! A drop in core temperature is part of your body’s sleep signal.', 'That’s why a cool room helps.', 'Sleep Foundation: Body temperature', 'draft', true, now()),
  ('sleep-cycle-4-02', 'sleep-cycle', 4, 'Melatonin is made mainly in the stomach.', 'myth', 'Deep in the brain.', 'Not true! The melatonin that controls sleep is made by the pineal gland in the brain.', 'The pineal gland is about the size of a grain of rice.', 'Sleep Foundation: Melatonin', 'draft', true, now()),
  ('sleep-cycle-4-03', 'sleep-cycle', 4, 'Teens release melatonin later at night than adults and young children do.', 'fact', 'Night owl phase.', 'Correct! This is why teens often feel more awake late at night.', 'It’s biology, not laziness.', 'Sleep Foundation: Teens and sleep', 'draft', true, now()),
  ('sleep-cycle-4-04', 'sleep-cycle', 4, 'Deep sleep mostly happens in the last few hours before you wake.', 'myth', 'First half or second half?', 'Not true! Most deep sleep happens in the first half of the night. REM sleep is more common later.', 'That’s why the start of the night matters.', 'Sleep Foundation: Stages of sleep', 'draft', true, now()),
  ('sleep-cycle-4-05', 'sleep-cycle', 4, 'Your body releases most of its growth hormone during deep sleep.', 'fact', 'Growing in your sleep.', 'Correct! Deep sleep is when much of the body’s repair and growth happens.', 'Teens need this sleep to grow.', 'Sleep Foundation: Stages of sleep', 'draft', true, now()),
  ('sleep-cycle-4-06', 'sleep-cycle', 4, 'During REM sleep, your muscles are at their most active.', 'myth', 'Paralysed?', 'Not true! Most muscles are temporarily switched off during REM so you don’t act out your dreams.', 'Your eye muscles and breathing keep working.', 'Sleep Foundation: Stages of sleep', 'draft', true, now()),
  ('sleep-cycle-4-07', 'sleep-cycle', 4, 'A full sleep cycle lasts roughly 90 minutes.', 'fact', 'Cycles within the night.', 'Correct! You go through several of these cycles each night.', 'Waking at the end of a cycle can feel easier.', 'Sleep Foundation: Stages of sleep', 'draft', true, now()),
  ('sleep-cycle-4-08', 'sleep-cycle', 4, 'Adenosine is a brain chemical that wakes you up.', 'myth', 'Builds up through the day.', 'Not true! Adenosine builds up during the day and makes you sleepy. Caffeine blocks it.', 'Sleep clears adenosine away.', 'Sleep Foundation: Caffeine and sleep', 'draft', true, now()),
  ('sleep-cycle-4-09', 'sleep-cycle', 4, 'Caffeine can stay in your body for 5 hours or more, so an afternoon drink can still affect sleep.', 'fact', 'Half-life.', 'Correct! Half the caffeine can still be around 5 hours later.', 'Some people are more sensitive than others.', 'Sleep Foundation: Caffeine and sleep', 'draft', true, now()),
  ('sleep-cycle-4-10', 'sleep-cycle', 4, 'Sleep problems before a period have nothing to do with hormones.', 'myth', 'What changes before a period?', 'Not true! Falling oestrogen and progesterone before a period are linked to poorer sleep for some people.', 'Tracking can help you spot this.', 'Sleep Foundation: Sleep and the menstrual cycle', 'draft', true, now()),
  ('sleep-cycle-5-01', 'sleep-cycle', 5, 'A part of the brain called the suprachiasmatic nucleus (SCN) is your body’s master clock.', 'fact', 'Above the optic nerves.', 'Correct! The SCN sits in the hypothalamus and uses light signals from your eyes.', 'It has only about 20,000 nerve cells.', 'Sleep Foundation: Circadian rhythm', 'draft', true, now()),
  ('sleep-cycle-5-02', 'sleep-cycle', 5, 'Red light at night has the strongest effect on your body clock.', 'myth', 'Which colour?', 'Not true! Blue light has the strongest effect. Dim, warm light is gentler.', 'Your eyes have special cells sensitive to blue light.', 'Sleep Foundation: Light and sleep', 'draft', true, now()),
  ('sleep-cycle-5-03', 'sleep-cycle', 5, 'Restless legs syndrome is more common in people with low iron.', 'fact', 'Iron and nerves.', 'Correct! Low iron is linked to restless legs, so doctors often check ferritin.', 'It can get worse in pregnancy.', 'NHS: Restless legs syndrome', 'draft', true, now()),
  ('sleep-cycle-5-04', 'sleep-cycle', 5, 'Sleep apnoea only happens in older men.', 'myth', 'Who else?', 'Not true! It can affect anyone, including women and people with PCOS.', 'Loud snoring and daytime sleepiness are clues.', 'NHS: Sleep apnoea', 'draft', true, now()),
  ('sleep-cycle-5-05', 'sleep-cycle', 5, 'In the second half of the cycle, people tend to get a little less REM sleep.', 'fact', 'Luteal changes.', 'Correct! Studies show REM sleep often dips in the luteal phase.', 'Light sleep may increase too.', 'Sleep Foundation: Sleep and the menstrual cycle', 'draft', true, now()),
  ('sleep-cycle-5-06', 'sleep-cycle', 5, 'Melatonin supplements are recommended for most teens who can’t sleep.', 'myth', 'Advice?', 'Not true! In the UK, melatonin is prescription-only and usually used for specific cases. Sleep habits come first.', 'Talk to a doctor before trying any sleep aid.', 'NHS: Melatonin', 'draft', true, now()),
  ('sleep-cycle-5-07', 'sleep-cycle', 5, 'Social jet lag is the gap between your sleep times on school days and free days.', 'fact', 'Weekend lie-ins.', 'Correct! A big gap can leave you feeling jet-lagged every Monday.', 'Keeping weekend sleep within an hour helps.', 'Sleep Foundation: Social jet lag', 'draft', true, now()),
  ('sleep-cycle-5-08', 'sleep-cycle', 5, 'Your body clock runs on exactly 24 hours without any help from daylight.', 'myth', 'Slightly off.', 'Not true! Most body clocks run a bit longer than 24 hours, and daylight resets them each day.', 'That’s why morning light matters.', 'Sleep Foundation: Circadian rhythm', 'draft', true, now()),
  ('sleep-cycle-5-09', 'sleep-cycle', 5, 'Around menopause, drops in oestrogen can cause hot flushes that wake people at night.', 'fact', 'Night sweats.', 'Correct! Hot flushes at night are a common reason for broken sleep around menopause.', 'Treatments can help.', 'NHS: Menopause', 'draft', true, now()),
  ('sleep-cycle-5-10', 'sleep-cycle', 5, 'Alcohol helps you get better-quality sleep.', 'myth', 'Knockout vs quality.', 'Not true! Alcohol may make you drowsy, but it disrupts sleep later in the night.', 'It reduces REM sleep too.', 'Sleep Foundation: Alcohol and sleep', 'draft', true, now())
